function migrateTtsProviderSettings(s) {
  if (!isPlainObject(s.tts)) s.tts = clone(DEFAULT_SETTINGS.tts);
  migrateTtsProviderSettingsState(s.tts);
  for (const provider of listTtsProviders()) assertTtsProviderContract(provider.id);

  const t = s.tts;
  if (!isPlainObject(t.extractSchemes)) t.extractSchemes = {};
  if (!isPlainObject(t.extractPrompts)) t.extractPrompts = {};
  if (!isPlainObject(t.extractPromptBackups)) t.extractPromptBackups = {};
  // 1.8.2 之前只有一份 MiniMax 自定义提示词；升级时保留为 MiniMax 的“我的自定义”。
  if (!t._extractPromptProviderMigrated) {
    const legacyPrompt = String(t.extractPrompt || '');
    if (legacyPrompt.trim()) {
      t.extractPrompts.minimax = legacyPrompt;
      t.extractSchemes.minimax = 'custom';
    }
    if (t.extractPromptBackup) t.extractPromptBackups.minimax = String(t.extractPromptBackup);
    delete t.extractPrompt;
    delete t.extractPromptBackup;
    t._extractPromptProviderMigrated = true;
  }
  for (const provider of listTtsProviders()) {
    const selected = t.extractSchemes[provider.id];
    const libraryId = String(selected || '').match(/^library:(.+)$/)?.[1] || '';
    const libraryExists = libraryId && Array.isArray(t.guidanceSchemes) && t.guidanceSchemes.some((item) => item.id === libraryId);
    if (!['provider', 'custom'].includes(selected) && !libraryExists) {
      t.extractSchemes[provider.id] = String(t.extractPrompts[provider.id] || '').trim() ? 'custom' : 'provider';
    }
    if (typeof t.extractPrompts[provider.id] !== 'string') t.extractPrompts[provider.id] = '';
  }
}

function ttsProviderId() {
  return normalizeTtsProviderId(settings?.tts?.provider);
}

function ttsProviderConfig(providerId = ttsProviderId()) {
  const t = settings.tts || (settings.tts = clone(DEFAULT_SETTINGS.tts));
  const id = normalizeTtsProviderId(providerId);
  if (!isPlainObject(t.providers)) t.providers = {};
  if (!isPlainObject(t.providers[id])) t.providers[id] = createTtsProviderDefaults(id);
  mergeDefaults(t.providers[id], createTtsProviderDefaults(id));
  return t.providers[id];
}

// ttsDoubaoVoiceModel 和 ttsDoubaoVoiceModelLabel 依赖 getTtsProvider，保留在主模块中
function ttsDoubaoVoiceModel(value, fallback = 'auto') {
  const model = String(value || '').trim();
  if (model === 'auto') return 'auto';
  const allowed = getTtsProvider('doubao').modelOptions || [];
  return allowed.some((item) => item.value === model) ? model : fallback;
}

function ttsDoubaoVoiceModelOptions(selected = 'auto', includeAuto = true) {
  const value = ttsDoubaoVoiceModel(selected);
  const options = includeAuto ? [{ value: 'auto', label: '自动识别' }] : [];
  options.push(...(getTtsProvider('doubao').modelOptions || []));
  return options.map((item) => `<option value="${htmlEscape(item.value)}" ${item.value === value ? 'selected' : ''}>${htmlEscape(item.label)}</option>`).join('');
}

function ttsDoubaoVoiceModelLabel(value) {
  if (value === 'auto' || !value) return '自动识别';
  return (getTtsProvider('doubao').modelOptions || []).find((item) => item.value === value)?.label || '自动识别';
}

function getSettings() {
  const context = ctx();
  const extensionSettings = context.extensionSettings || (context.extensionSettings = {});
  if (!isPlainObject(extensionSettings[MODULE_NAME])) extensionSettings[MODULE_NAME] = clone(DEFAULT_SETTINGS);
  // 仓库名、插件显示名可更新，但持久化命名空间永远保持 story_director_liminale。
  // 先跑只增不删的 V2 兼容门面，再补新默认，避免默认值抢占旧字段的迁移目标。
  extensionSettings[MODULE_NAME] = acceptMigrationResult('settings', migrateQianmuSettingsV2(extensionSettings[MODULE_NAME]));
  mergeDefaults(extensionSettings[MODULE_NAME], DEFAULT_SETTINGS);
  const cachedProse = readCachedProseLayout();
  const storedProse = extensionSettings[MODULE_NAME].proseLayout;
  if (cachedProse && Number(cachedProse.updatedAt || 0) > Number(storedProse?.updatedAt || 0)) {
    extensionSettings[MODULE_NAME].proseLayout = clone(cachedProse);
  }
  migrateSettings(extensionSettings[MODULE_NAME]);
  return extensionSettings[MODULE_NAME];
}

function acceptMigrationResult(scope, result) {
  const previous = migrationRuntime[scope] || { status: 'idle', error: '', at: 0 };
  if (result?.failed) {
    const error = String(result.error || '未知迁移错误').slice(0, 500);
    migrationRuntime[scope] = { status: 'rolled_back', error, at: Date.now() };
    if (previous.status !== 'rolled_back' || previous.error !== error) {
      console.warn(`[千幕] ${scope === 'settings' ? '设置' : '聊天'}数据迁移失败，已保留原数据并回退。`, error);
    }
  } else {
    migrationRuntime[scope] = { status: result?.changed ? 'migrated' : 'ready', error: '', at: Date.now() };
  }
  return result?.value;
}

function migrateSettings(s) {
  migrateTtsProviderSettings(s);
  // v1.58.15：退役伏笔显影的全局开关与注入位，避免旧设置继续影响提示词构建。
  delete s.liveStageEnabled;
  if (isPlainObject(s.injectSections)) delete s.injectSections.threads;
  if (typeof s.maxContextMessages !== 'undefined' && typeof s.contextOptions?.contextDepth === 'undefined') {
    s.contextOptions.contextDepth = Number(s.maxContextMessages) || 5;
  }
  delete s.maxContextMessages;
  if (typeof s.outputSchemaText === 'undefined') s.outputSchemaText = JSON_SCHEMA_TEXT;

  // ── 幕后提示词/输出格式：内容哈希驱动的「更新即覆盖」──
  // 旧策略只在 promptRevision 升档时才覆盖，而多数默认文本改动「不占 REV」，导致新版默认已变、
  // 但用户端不覆盖，必须手动点「恢复默认」才更新——本次根治：记录「本机已落地的默认文本哈希」，
  // 只要打包内的默认文本与它不符（＝推了新版默认），就无条件用新默认覆盖当前幕后设置；
  // 覆盖前无条件把当前内容存进「恢复上次」快照（不论用户是否改过），用户可一键找回。
  const curDefSysHash = hashText(DEFAULT_SYSTEM_PROMPT);
  const curDefSchemaHash = hashText(JSON_SCHEMA_TEXT);
  // 首次进入本机制（appliedPromptDefaultHash 尚未落地）：先判定当前值是否为「历史内置默认」，
  // 是则视作已落地旧默认（可安全覆盖、不留无谓快照）；否则视作用户 DIY（覆盖前留快照）。
  if (typeof s.appliedPromptDefaultHash === 'undefined') {
    const sys = String(s.systemPrompt || '');
    const sysIsLegacyDefault = !sys.trim()
      || sys.includes('你是一位顶尖剧作家导演')
      || (sys.includes('顶尖剧作家导演') && !sys.includes('视角分工'))
      || sys.includes('执笔者（使用者）')
      || sys === DEFAULT_SYSTEM_PROMPT
      || (s.systemPromptHash && s.systemPromptHash === hashText(sys) && sys === DEFAULT_SYSTEM_PROMPT);
    // 旧默认→标记为「上一版默认哈希」，触发下方覆盖但不留快照；DIY→标记为空，触发覆盖且留快照
    s.appliedPromptDefaultHash = sysIsLegacyDefault ? '__legacy__' : '';
    s._promptFirstSeedLegacy = sysIsLegacyDefault;
  }
  if (typeof s.appliedSchemaDefaultHash === 'undefined') {
    const schema = String(s.outputSchemaText || '');
    const schemaIsLegacyDefault = !schema.trim()
      || (schema.includes('schema_version')
          && (!schema.includes('全知导演镜头') || (schema.includes('导演评语：分析节奏') && !schema.includes('毒舌影评人'))))
      || schema === JSON_SCHEMA_TEXT;
    s.appliedSchemaDefaultHash = schemaIsLegacyDefault ? '__legacy__' : '';
    s._schemaFirstSeedLegacy = schemaIsLegacyDefault;
  }

  if (s.appliedPromptDefaultHash !== curDefSysHash) {
    const sys = String(s.systemPrompt || '');
    // 覆盖前留快照：仅当当前内容确有价值（非空、且非本次打包的新默认、且非首次识别出的历史内置默认）
    const worthBackup = sys.trim() && sys !== DEFAULT_SYSTEM_PROMPT && !s._promptFirstSeedLegacy;
    if (worthBackup) s.systemPromptBackup = sys;
    s.systemPrompt = DEFAULT_SYSTEM_PROMPT;
    s.appliedPromptDefaultHash = curDefSysHash;
  }
  if (s.appliedSchemaDefaultHash !== curDefSchemaHash) {
    const schema = String(s.outputSchemaText || '');
    const worthBackup = schema.trim() && schema !== JSON_SCHEMA_TEXT && !s._schemaFirstSeedLegacy;
    if (worthBackup) s.outputSchemaBackup = schema;
    s.outputSchemaText = JSON_SCHEMA_TEXT;
    s.appliedSchemaDefaultHash = curDefSchemaHash;
  }
  delete s._promptFirstSeedLegacy;
  delete s._schemaFirstSeedLegacy;
  s.promptRevision = PROMPT_REVISION;
  // 记录当前默认文本的哈希：与默认一致则存哈希（标记“未改动”），不一致则清空（标记“已 DIY”）
  s.systemPromptHash = String(s.systemPrompt || '') === DEFAULT_SYSTEM_PROMPT ? hashText(DEFAULT_SYSTEM_PROMPT) : '';
  s.outputSchemaHash = String(s.outputSchemaText || '') === JSON_SCHEMA_TEXT ? hashText(JSON_SCHEMA_TEXT) : '';

  if (!Array.isArray(s.logHistory)) s.logHistory = [];
  if (!isPlainObject(s.logOpenState)) s.logOpenState = {};
  if (s.lastLog && typeof s.lastLog === 'object') {
    if (s.lastLog.status && s.lastLog.status !== 'none') {
      s.logHistory.unshift({
        id: uid('log'),
        status: s.lastLog.status === 'loading' ? 'cancelled' : s.lastLog.status,
        time: s.lastLog.time || '',
        duration: s.lastLog.duration || '',
        request: String(s.lastLog.request || ''),
        response: String(s.lastLog.response || ''),
        error: s.lastLog.error || '',
      });
  s.logHistory = s.logHistory.slice(0, LOG_LIMIT);
  const validLogIds = new Set(s.logHistory.map((log) => String(log?.id || '')).filter(Boolean));
  Object.keys(s.logOpenState).forEach((id) => { if (!validLogIds.has(id)) delete s.logOpenState[id]; });
    }
    delete s.lastLog;
  }

  if (!Array.isArray(s.apiProfiles)) s.apiProfiles = [];
  s.structuredOutputMode = normalizeQianmuStructuredOutputMode(s.structuredOutputMode);
  s.apiProfiles = s.apiProfiles.map((profile) => isPlainObject(profile)
    ? { ...profile, structuredOutputMode: normalizeQianmuStructuredOutputMode(profile.structuredOutputMode) }
    : profile);
  s.selectedPresetNamesByChat ||= {};
  s.selectedPresetItemsByChat ||= {};
  s.selectedWorldBookNamesByChat ||= {};
  s.selectedWorldBookItemsByChat ||= {};
  s.globalWorldBookNames ||= {};
  // 预设勾选 按聊天 → 全局 一次性迁移（取条目最丰富的那个聊天作为种子，避免丢失既有搭配）
  s.selectedPresetNames ||= {};
  s.selectedPresetItems ||= {};
  if (!s._presetGlobalMigrated) {
    if (!Object.keys(s.selectedPresetNames).length) {
      const pickRichest = (byChat) => Object.values(byChat || {})
        .reduce((best, cur) => (Object.keys(cur || {}).length > Object.keys(best || {}).length ? cur : best), {});
      const seedNames = pickRichest(s.selectedPresetNamesByChat);
      const seedItems = pickRichest(s.selectedPresetItemsByChat);
      if (Object.keys(seedNames).length) s.selectedPresetNames = clone(seedNames);
      if (Object.keys(seedItems).length) s.selectedPresetItems = clone(seedItems);
    }
    s._presetGlobalMigrated = true;
  }
  if (!isPlainObject(s.theater)) s.theater = { instruction: '', apiProfileId: '', presetName: '', presetItems: {}, scripts: [], favorites: [], lastOutput: null };
  if (!Array.isArray(s.theater.scripts)) s.theater.scripts = [];
  if (!Array.isArray(s.theater.favorites)) s.theater.favorites = [];
  if (!isPlainObject(s.theater.presetItems)) s.theater.presetItems = {};
  if (!Array.isArray(s.templates)) s.templates = [];
  // tags → folder：取首个旧标签作为文件夹，移除 tags 字段
  s.templates = s.templates.map((tpl) => {
    const folder = typeof tpl.folder === 'string'
      ? sanitizeFolder(tpl.folder)
      : sanitizeFolder(Array.isArray(tpl.tags) ? tpl.tags[0] : '');
    const { tags, ...rest } = tpl;
    return { ...rest, folder };
  });
  if (s.contextOptions) {
    if (!Array.isArray(s.contextOptions.tagRules)) {
      const names = String(s.contextOptions.tagNames || '').split(/[,，\s\n]+/).map((x) => x.trim()).filter(Boolean);
      const action = s.contextOptions.tagMode === 'extract' || s.contextOptions.extractTags ? 'extract' : 'remove';
      s.contextOptions.tagRules = (names.length ? names : ['thinking']).map((name) => ({ name: name.replace(/^<|>$/g, ''), action }));
    }
    delete s.contextOptions.tagMode;
    delete s.contextOptions.tagNames;
    delete s.contextOptions.removeTags;
    delete s.contextOptions.extractTags;
    delete s.contextOptions.manualContext;
    delete s.contextOptions.presetNames;
    delete s.contextOptions.worldBookNames;
    delete s.contextOptions.removeHtmlComments;
  }
}

function pushLog(entry) {
  settings.logHistory ||= [];
  settings.logOpenState ||= {};
  settings.logHistory.unshift(entry);
  settings.logHistory = settings.logHistory.slice(0, LOG_LIMIT);
  if (entry?.id) settings.logOpenState[entry.id] = false;
  const validIds = new Set(settings.logHistory.map((log) => String(log?.id || '')).filter(Boolean));
  Object.keys(settings.logOpenState).forEach((id) => { if (!validIds.has(id)) delete settings.logOpenState[id]; });
  saveSettings();
  return entry;
}

function saveSettings() {
  ctx().saveSettingsDebounced?.();
}

async function saveMetadata() {
  if (typeof ctx().saveMetadata === 'function') await ctx().saveMetadata();
}

function getChatKey() {
  const context = ctx();
  return context.chatId || context.groupId || String(context.characterId ?? 'default');
}

function getChatStore() {
  const context = ctx();
  const meta = context.chatMetadata || (context.chatMetadata = {});
  if (!meta[MODULE_NAME]) {
    meta[MODULE_NAME] = { blueprint: DEFAULT_BLUEPRINT, plan: null, history: [], lastPlanIdx: -1, planAtLen: 0, updatedAt: '', factions: [], worldEvents: [], geoSeq: 0 };
  }
  meta[MODULE_NAME] = acceptMigrationResult('chat', migrateQianmuChatStoreV2(meta[MODULE_NAME]));
  mergeDefaults(meta[MODULE_NAME], { blueprint: DEFAULT_BLUEPRINT, plan: null, history: [], lastPlanIdx: -1, planAtLen: 0, updatedAt: '', factions: [], worldEvents: [], geoSeq: 0 });
  // v1.58.15：伏笔显影已退役。聊天在被打开时惰性清理旧档案，避免继续占用元数据或误入提示词。
  delete meta[MODULE_NAME].threads;
  delete meta[MODULE_NAME].threadSeq;
  delete meta[MODULE_NAME].threadRecallIds;
  delete meta[MODULE_NAME].threadQuality;
  if (!Array.isArray(meta[MODULE_NAME].factions)) meta[MODULE_NAME].factions = [];   // 活幕·势：势力/地缘格局层
  if (!Array.isArray(meta[MODULE_NAME].worldEvents)) meta[MODULE_NAME].worldEvents = [];   // 活幕·势：世界事件层
  if (!meta[MODULE_NAME].ttsLines || typeof meta[MODULE_NAME].ttsLines !== 'object') meta[MODULE_NAME].ttsLines = {};   // 有声：已提取台词列表 内容指纹key→lines，持久化跨刷新
  if (!meta[MODULE_NAME].ttsLineKeyByMes || typeof meta[MODULE_NAME].ttsLineKeyByMes !== 'object') meta[MODULE_NAME].ttsLineKeyByMes = {};   // 有声：楼层mesid→最近一次台词key，原地编正文后凭此+台词原文在场校验迁移缓存（免重提）
  if (!isPlainObject(meta[MODULE_NAME].ttsVoiceMaps)) meta[MODULE_NAME].ttsVoiceMaps = {};   // 配音：按 Provider 隔离的本聊天角色→音色映射
  if (!Array.isArray(meta[MODULE_NAME].storyboardImages)) meta[MODULE_NAME].storyboardImages = [];   // 分镜：只存图片 URL/镜头参数/楼层锚点，不改正文 mes
  if (Array.isArray(meta[MODULE_NAME].ttsVoiceMap) && !Array.isArray(meta[MODULE_NAME].ttsVoiceMaps.minimax)) {
    meta[MODULE_NAME].ttsVoiceMaps.minimax = meta[MODULE_NAME].ttsVoiceMap;   // 1.8.1 旧映射无损迁移
  }
  // 首个 V2 周期保留旧 ttsVoiceMap 作为回退读口；新代码只使用 ttsVoiceMaps，不再写旧键。
  if (isLegacyBlueprint(meta[MODULE_NAME].blueprint) && !meta[MODULE_NAME].blueprintEdited) {
    meta[MODULE_NAME].blueprint = DEFAULT_BLUEPRINT;
  }
  // 剧本模板更新：BLUEPRINT_REVISION 升档后，新默认覆盖本聊天剧本；覆盖前若为用户 DIY 则备份进「恢复上次」。
  // 新建 store 的 blueprint 即默认值、不算 DIY，只盖版本号不备份；故仅真·DIY 会写入 blueprintBackup。
  if (Number(meta[MODULE_NAME].blueprintRevision || 0) < BLUEPRINT_REVISION) {
    const bp = String(meta[MODULE_NAME].blueprint || '');
    const bpDiy = !!meta[MODULE_NAME].blueprintEdited && bp.trim()
      && !isLegacyBlueprint(bp) && bp !== DEFAULT_BLUEPRINT;
    if (bpDiy) meta[MODULE_NAME].blueprintBackup = bp;
    meta[MODULE_NAME].blueprint = DEFAULT_BLUEPRINT;
    meta[MODULE_NAME].blueprintEdited = false;
    meta[MODULE_NAME].blueprintRevision = BLUEPRINT_REVISION;
  }
  return meta[MODULE_NAME];
}

