async function fetchModels() {
  try {
    const rawUrl = String(settings.apiUrl || '').trim().replace(/\/+$/, '');
    if (!rawUrl || !settings.apiKey) throw new Error('missing');
    // 借 ST 后端代理拉取（绕过浏览器 CORS）；原始 URL 交后端拼 /models 路径
    let res = await fetchViaSTProxy(rawUrl, `Authorization: Bearer ${settings.apiKey}`);
    if (!res.ok && (res.status === 401 || res.status === 403)) {
      res = await fetchViaSTProxy(rawUrl, `Authorization: ${settings.apiKey}`);
    }
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    // 兼容多种返回结构：{models:[]} / {data:[]} / 顶层数组；元素可为字符串或 {id}/{name} 对象
    let list = [];
    if (data && Array.isArray(data.models)) list = data.models;
    else if (data && Array.isArray(data.data)) list = data.data;
    else if (Array.isArray(data)) list = data;
    settings.availableModels = list
      .map((x) => typeof x === 'string' ? x : x?.id || x?.name)
      .filter(Boolean);
    if (!settings.model && settings.availableModels.length) settings.model = settings.availableModels[0];
    saveSettings();
    toast(`已拉取 ${settings.availableModels.length} 个模型。`, 'success');
    renderModal();
  } catch (_) {
    apiToast();
  }
}

function stopGeneration() {
  cancelRequested = true;
  if (abortController) abortController.abort();
  const loading = (settings.logHistory || []).find((x) => x.status === 'loading' && x.kind !== 'theater');
  if (loading) {
    loading.status = 'cancelled';
    loading.error = '已取消生成';
  }
  saveSettings();
  busy = false;
  renderBusyState();
  rerenderIfOpen();
  // 取消提示统一由生成流程的 catch 负责，避免在此重复弹出
}

// 幕外停止：只中止幕外这条链路，绝不影响正在跑的推演
function stopTheater() {
  theaterCancel = true;
  if (theaterAbort) theaterAbort.abort();
  const loading = (settings.logHistory || []).find((x) => x.status === 'loading' && x.kind === 'theater');
  if (loading) {
    loading.status = 'cancelled';
    loading.error = '已取消生成';
  }
  saveSettings();
  theaterBusy = false;
  renderBusyState();
  rerenderIfOpen();
}

function injectToInput(text) {
  const value = String(text || '').trim();
  if (!value) return false;
  try {
    const context = ctx();
    if (typeof context.setInputText === 'function') {
      context.setInputText(value);
      return true;
    }
  } catch (_) {}
  try {
    if (typeof globalThis.triggerSlash === 'function') {
      globalThis.triggerSlash('/setinput ' + value);
      return true;
    }
  } catch (_) {}
  const selectors = ['#send_textarea', 'textarea#send_textarea', 'textarea[name="user_input"]', '#chat-input textarea', 'textarea'];
  const input = selectors.flatMap((s) => Array.from(document.querySelectorAll(s))).find((el) => !el.disabled && !el.readOnly);
  if (!input) return false;
  input.focus();
  const proto = input.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
  const descriptor = Object.getOwnPropertyDescriptor(proto, 'value');
  if (descriptor?.set) descriptor.set.call(input, value); else input.value = value;
  input.dispatchEvent(new Event('input', { bubbles: true }));
  input.dispatchEvent(new Event('change', { bubbles: true }));
  return true;
}
// 校验一个 tab id 当前是否可落脚：coread 隐藏时、geopolitics 关闭时回落 dashboard。
// 用于「二次打开恢复上次 tab」——记录的 tab 若因开关变化已不可用，安全回落首页。
function resolveRestorableTab(tab) {
  // v1.30 起「编剧」并入「幕后」。旧设置里若仍记着 blueprint，直接迁移到 settings，
  // 避免更新后恢复到一个已经撤掉的顶层入口。
  if (tab === 'blueprint') return 'settings';
  if (tab === 'imagegen') return 'dashboard';
  if (tab === 'geopolitics') return 'castworld';
  const KNOWN = ['dashboard', 'focus', 'tasksnodes', 'castworld', 'context', 'settings', 'theater', 'tts', 'imagegen', 'geopolitics', 'coread', 'plug'];
  if (!KNOWN.includes(tab)) return 'dashboard';
  if (tab === 'coread' && !COREAD_ENABLED) return 'dashboard';
  return tab;
}

function openModal(tab) {
  if (!settings.enabled) return toast('千幕已关闭。', 'warning');
  performanceRuntime.modalOpenCount += 1;
  seedBuiltinTheaters();   // 开窗渲染前补种：根除「更新后首开剧札为空、需重开才显示」（幂等，两组 revision 最新即早退）
  // tab 显式传入则用之；否则恢复上次停留的标签（校验回退）——修「不管上次停在哪，重开都回首页」。
  const requestedTab = tab != null ? tab : (settings.lastTab || 'dashboard');
  if (tab === 'imagegen') {
    storyboardReturnTab = resolveRestorableTab(settings.lastTab || 'dashboard');
    storyboardBeginSession();
    activeTab = 'imagegen';
  } else if (requestedTab === 'geopolitics') {
    if (!settings.geopoliticsEnabled) {
      if (tab === 'geopolitics') toast('请先在幕后开启「活幕·势」。', 'info');
      activeTab = 'dashboard';
    } else {
      worldPage = 'geopolitics';
      activeTab = 'castworld';
    }
  } else {
    activeTab = resolveRestorableTab(requestedTab);
  }
  theaterView = null;
  let modal = document.getElementById(MODAL_ID);
  if (!modal) {
    modal = document.createElement('div');
    modal.id = MODAL_ID;
    document.body.appendChild(modal);
  }
  modalJustOpened = true;   // 标记首帧需入场动画；renderModal 消费后即清，后续静默重渲染不再播
  modal.classList.add('open');
  document.body.classList.add('sd-qm-modal-open');   // 压制 ST 快捷回复栏：搜索框聚焦不再牵出 QR 栏（CSS 端按此类隐藏）
  renderModal();
  void refreshQianmuUpdateStatus();
}

function closeModal() {
  if (activeTab === 'imagegen') {
    const storyboardRoot = document.getElementById(MODAL_ID)?.querySelector('.sd-storyboard-root');
    if (storyboardRoot && storyboardState().view === 'create') storyboardCaptureWorkbench(storyboardRoot);
    storyboardCloseLightbox();
    storyboardCloseVideoViewer();
    storyboardCloseFilmViewer();
    storyboardGallerySelection.clear();
    storyboardEndSession();
  }
  focusClockCloseVoiceDrawer();
  document.getElementById(MODAL_ID)?.classList.remove('open');
  document.body.classList.remove('sd-qm-modal-open');
  unmountReaderPortal();   // 关模态连带收掉全屏阅读 portal
  unmountTheaterFullscreen();   // 关模态连带收掉幕外全屏阅读 portal
}

// 行内全屏文本编辑（编剧/幕后提示词/此幕指令共用）：在千幕界面内切换出编辑视图，沿用阅读页布局+吸顶返回/保存，
// 不另在 body 挂独立窗口（窄屏 fixed 定位会以 .sd-window 为基准跑偏）。
function openTextEditor({ target, title, value, placeholder = '', commit }) {
  // 记住进入编辑器前的正文滚动位，关闭后恢复——否则 renderModal 会把页面弹回顶部
  ttsEditorReturnScroll = document.getElementById(MODAL_ID)?.querySelector('.sd-body')?.scrollTop ?? 0;
  editorView = { target, title: title || '编辑', value: value || '', placeholder, commit, returnTab: activeTab };
  renderModal();
}

function closeEditorView() {
  editorView = null;
  renderModal();
  const body = document.getElementById(MODAL_ID)?.querySelector('.sd-body');
  if (body && ttsEditorReturnScroll != null) body.scrollTop = ttsEditorReturnScroll;
  ttsEditorReturnScroll = null;
}

// 行内编辑保存：按 target 直写对应数据模型，与各自原有持久化口径一致
async function commitEditorValue(target, val) {
  if (target === 'sd-blueprint') {
    getChatStore().blueprint = val || DEFAULT_BLUEPRINT;
    getChatStore().blueprintEdited = true;
    await saveMetadata();
  } else if (target === 'sd-system-prompt') {
    settings.systemPrompt = val || DEFAULT_SYSTEM_PROMPT;
    settings.systemPromptHash = settings.systemPrompt === DEFAULT_SYSTEM_PROMPT ? hashText(DEFAULT_SYSTEM_PROMPT) : '';
    saveSettings();
  } else if (target === 'sd-inject-preview') {
    getChatStore().injectOverride = String(val ?? '').trim();
    await saveMetadata();
    await applyDirectorInjection();
  } else if (target === 'sd-theater-instruction') {
    getTheater().instruction = val || '';
    theaterScriptSource = '';   // 手动改动即视为即兴，脱离剧札来源
    saveSettings();
  } else if (target.startsWith('ttsscheme:')) {
    const id = target.slice('ttsscheme:'.length);
    const schemes = settings.tts?.guidanceSchemes || [];
    const sch = schemes.find((x) => x.id === id);
    if (sch) { sch.content = val || ''; saveSettings(); }
  }
}

function renderEditorView() {
  const ev = editorView;
  const injectionEditor = ev.target === 'sd-inject-preview';
  return `
    <section class="sd-card sd-reader-card sd-editor-card">
      <div class="sd-sticky-bar sd-editor-bar">
        ${injectionEditor ? '<button type="button" class="sd-icon-btn sd-editor-tool-icon sd-editor-back" title="返回" aria-label="返回"><i class="fa-solid fa-arrow-left"></i></button>' : '<button type="button" class="sd-btn sd-mini-btn sd-editor-back"><i class="fa-solid fa-arrow-left"></i>返回</button>'}
        <h3>${htmlEscape(ev.title)}</h3>
        <div class="sd-editor-actions">${injectionEditor ? '<button type="button" class="sd-icon-btn sd-editor-tool-icon sd-editor-reset-injection" title="恢复自动生成" aria-label="恢复自动生成"><i class="fa-solid fa-arrow-rotate-left"></i></button><button type="button" class="sd-icon-btn sd-editor-tool-icon sd-primary sd-editor-save" title="保存" aria-label="保存"><i class="fa-solid fa-check"></i></button>' : '<button type="button" class="sd-btn sd-mini-btn sd-primary sd-editor-save"><i class="fa-solid fa-check"></i>保存</button>'}</div>
      </div>
      <textarea class="text_pole sd-editor-area" spellcheck="false" placeholder="${htmlEscape(ev.placeholder)}">${htmlEscape(ev.value)}</textarea>
    </section>`;
}

function renderSettingsPanel() {
  document.getElementById(SETTINGS_PANEL_ID)?.remove();
}

function getFloatSize() {
  const responsiveDefault = window.matchMedia?.('(max-width: 760px)')?.matches ? 44 : 48;
  const configured = Number(settings.floatSize);
  return Number.isFinite(configured) && configured >= FLOAT_SIZE_MIN
    ? Math.max(FLOAT_SIZE_MIN, Math.min(FLOAT_SIZE_MAX, configured))
    : responsiveDefault;
}

function floatViewportBounds() {
  const viewport = window.visualViewport;
  const finite = (value, fallback) => Number.isFinite(Number(value)) ? Number(value) : fallback;
  const left = finite(viewport?.offsetLeft, 0);
  const top = finite(viewport?.offsetTop, 0);
  const width = Math.max(1, finite(viewport?.width, finite(window.innerWidth, 1)));
  const height = Math.max(1, finite(viewport?.height, finite(window.innerHeight, 1)));
  let safeTop = top + 4;
  // ST 顶栏层级高于千幕悬浮格。只识别横向、贴顶且高度有限的栏，避免把侧栏主题误判成整页安全区。
  if (typeof document?.querySelectorAll === 'function' && typeof globalThis.getComputedStyle === 'function') {
    const selectors = ['#top-settings-holder', '#top-bar', '.top-settings-holder', '.top-bar'];
    const seen = new Set();
    for (const element of document.querySelectorAll(selectors.join(','))) {
      if (!(element instanceof Element) || seen.has(element)) continue;
      seen.add(element);
      const style = globalThis.getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      const overlap = Math.max(0, Math.min(left + width, rect.right) - Math.max(left, rect.left));
      const shallow = rect.height > 0 && rect.height <= Math.min(140, height * .28);
      const touchesTop = rect.top <= top + 12 && rect.bottom > top;
      const spansHeader = overlap >= Math.min(width * .42, 280);
      if (style.display !== 'none' && style.visibility !== 'hidden' && shallow && touchesTop && spansHeader) {
        safeTop = Math.max(safeTop, Math.min(top + height, rect.bottom + 4));
      }
    }
  }
  return { left, top, width, height, right: left + width, bottom: top + height, safeTop };
}

function clampFloatPosition() {
  settings.floatPosition ||= { x: null, y: null };
  const size = getFloatSize();
  // 竖向正六边形：上下为尖角、左右为直边；size 表示视觉高度，宽度按 √3/2 收窄。
  const width = size * QUICK_HEX_WIDTH_RATIO;
  const height = size;
  const margin = 4;
  const viewport = floatViewportBounds();
  // 跨 PC / 窄屏时按相对位置重算；仍允许用户主动半藏一条边，但任何尺寸下至少保留半格可拖区域。
  const minX = viewport.left - width / 2;
  const minY = Math.min(viewport.safeTop, Math.max(viewport.top, viewport.bottom - height));
  const maxX = Math.max(minX, viewport.right - width / 2);
  const maxY = Math.max(minY, viewport.bottom - height / 2);
  const rawXValue = settings.floatPosition.x;
  const rawYValue = settings.floatPosition.y;
  let rawX = rawXValue == null || rawXValue === '' ? Number.NaN : Number(rawXValue);
  let rawY = rawYValue == null || rawYValue === '' ? Number.NaN : Number(rawYValue);
  const previousWidth = Number(settings.floatPosition.viewportWidth);
  const previousHeight = Number(settings.floatPosition.viewportHeight);
  const ratioX = Number(settings.floatPosition.ratioX);
  const ratioY = Number(settings.floatPosition.ratioY);
  const viewportChanged = Number.isFinite(previousWidth) && Number.isFinite(previousHeight)
    && (Math.abs(previousWidth - viewport.width) > 1 || Math.abs(previousHeight - viewport.height) > 1);
  if (viewportChanged && Number.isFinite(ratioX) && Number.isFinite(ratioY)) {
    rawX = minX + Math.max(0, Math.min(1, ratioX)) * Math.max(0, maxX - minX);
    rawY = minY + Math.max(0, Math.min(1, ratioY)) * Math.max(0, maxY - minY);
  }
  const fallbackX = Math.max(viewport.left + margin, viewport.right - width - margin);
  const fallbackY = Math.max(minY, viewport.bottom - height - 84);
  settings.floatPosition.x = Math.min(maxX, Math.max(minX, Number.isFinite(rawX) ? rawX : fallbackX));
  settings.floatPosition.y = Math.min(maxY, Math.max(minY, Number.isFinite(rawY) ? rawY : fallbackY));
  const hiddenX = settings.floatPosition.x < viewport.left || settings.floatPosition.x + width > viewport.right;
  const hiddenY = settings.floatPosition.y < minY || settings.floatPosition.y + height > viewport.bottom;
  if (hiddenX && hiddenY) {
    const xDepth = Math.max(viewport.left - settings.floatPosition.x, settings.floatPosition.x + width - viewport.right) / width;
    const yDepth = Math.max(minY - settings.floatPosition.y, settings.floatPosition.y + height - viewport.bottom) / height;
    if (xDepth >= yDepth) settings.floatPosition.y = Math.min(viewport.bottom - height, Math.max(minY, settings.floatPosition.y));
    else settings.floatPosition.x = Math.min(viewport.right - width, Math.max(viewport.left, settings.floatPosition.x));
  }
  settings.floatPosition.ratioX = maxX > minX ? (settings.floatPosition.x - minX) / (maxX - minX) : 0;
  settings.floatPosition.ratioY = maxY > minY ? (settings.floatPosition.y - minY) / (maxY - minY) : 0;
  settings.floatPosition.viewportWidth = viewport.width;
  settings.floatPosition.viewportHeight = viewport.height;
  // 不可展开 viewport：其中的 height 会覆盖六边形视觉高度，导致按钮被拉成整屏长条。
  return {
    x: settings.floatPosition.x,
    y: settings.floatPosition.y,
    size: width,
    height,
    margin,
    minX,
    minY,
    maxX,
    maxY,
    left: viewport.left,
    top: viewport.top,
    right: viewport.right,
    bottom: viewport.bottom,
    safeTop: viewport.safeTop,
    viewportWidth: viewport.width,
    viewportHeight: viewport.height,
  };
}

function floatPositionIsHidden(pos = clampFloatPosition()) {
  return pos.x < pos.left || pos.y < pos.minY || pos.x + pos.size > pos.right || pos.y + pos.height > pos.bottom;
}

function applyFloatPosition(btn) {
  const pos = clampFloatPosition();
  const revealed = btn?.classList.contains('sd-float-revealed');
  const x = revealed ? Math.min(pos.right - pos.size, Math.max(pos.left, pos.x)) : pos.x;
  const y = revealed ? Math.min(pos.bottom - pos.height, Math.max(pos.minY, pos.y)) : pos.y;
  const width = `${pos.size}px`;
  const height = `${pos.height}px`;
  // 六边形的视觉尺寸与视口尺寸使用不同字段，且入口宽高始终由同一几何真源写入。
  btn.style.setProperty('width', width, 'important');
  btn.style.setProperty('min-width', width, 'important');
  btn.style.setProperty('max-width', width, 'important');
  btn.style.setProperty('height', height, 'important');
  btn.style.setProperty('min-height', height, 'important');
  btn.style.setProperty('max-height', height, 'important');
  btn.style.setProperty('left', `${x}px`, 'important');
  btn.style.setProperty('top', `${y}px`, 'important');
  btn.style.setProperty('right', 'auto', 'important');
  btn.style.setProperty('bottom', 'auto', 'important');
  btn.style.setProperty('box-sizing', 'border-box', 'important');
  btn.style.setProperty('flex', '0 0 auto', 'important');
}

function clearFloatRevealTimer(btn) {
  if (!btn?._sdRevealTimer) return;
  clearTimeout(btn._sdRevealTimer);
  btn._sdRevealTimer = null;
}

function concealFloatButton(btn, delay = 0, force = false) {
  if (!(btn instanceof Element)) return;
  clearFloatRevealTimer(btn);
  const run = () => {
    btn._sdRevealTimer = null;
    if (!force && btn.matches(':hover') && window.matchMedia?.('(hover: hover) and (pointer: fine)')?.matches) return;
    if ((btn.dataset.activePointer && btn.hasPointerCapture?.(Number(btn.dataset.activePointer))) || document.getElementById(QUICK_WHEEL_ID)) return;
    btn.classList.remove('sd-float-revealed');
    applyFloatPosition(btn);
  };
  if (delay > 0) btn._sdRevealTimer = setTimeout(run, delay);
  else run();
}

function revealFloatButton(btn, { temporary = true } = {}) {
  if (!(btn instanceof Element) || !floatPositionIsHidden()) return false;
  clearFloatRevealTimer(btn);
  btn.classList.add('sd-float-revealed');
  applyFloatPosition(btn);
  if (temporary) btn._sdRevealTimer = setTimeout(() => concealFloatButton(btn, 0, true), 2600);
  return true;
}

