// quickDockAttrEscape - 已迁移到 qianmu-storyboard-utils.js
// function quickDockAttrEscape(value) {
//   return String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\r\n]/g, ' ');
