function storageJsonBytes(value) {
  try {
    const text = JSON.stringify(value);
    if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(text).byteLength;
    return new Blob([text]).size;
  } catch (_) { return 0; }
}

function formatStorageBytes(value) {
  const bytes = Math.max(0, Number(value) || 0);
  if (bytes < 1024) return `${Math.round(bytes)} B`;
  const units = ['KB', 'MB', 'GB', 'TB'];
  let amount = bytes / 1024;
  let unit = units[0];
  for (let index = 1; index < units.length && amount >= 1024; index++) {
    amount /= 1024;
    unit = units[index];
  }
  return `${amount >= 100 ? amount.toFixed(0) : amount >= 10 ? amount.toFixed(1) : amount.toFixed(2)} ${unit}`;
}

function lazyFeatureDetail(features = featureRuntime.snapshot()) {
  return features.map((feature) => `${feature.label} · ${feature.status === 'ready' ? '已加载' : feature.status === 'loading' ? '加载中' : feature.status === 'error' ? '可重试' : '待命'}`).join(' · ') || '无';
}

function optionalServiceLabel() {
  if (optionalServiceState.status === 'checking') return '检测中';
  if (optionalServiceState.status === 'ready') return optionalServiceState.version ? `可用 · v${optionalServiceState.version}` : '可用';
  if (optionalServiceState.status === 'missing') return '未安装（可选）';
  if (optionalServiceState.status === 'unsupported') return '当前环境不支持';
  if (optionalServiceState.status === 'error') return '暂不可达';
  return '尚未检查';
}

function optionalServiceDetail() {
  if (optionalServiceState.status === 'ready') {
    const labels = { 'doubao-tts': '豆包语音网关', 'storyboard-image': '分镜跨域网关', 'minimax-h3': 'MiniMax H3 动态网关' };
    return optionalServiceState.services.map((service) => labels[service] || service).join(' · ') || '服务已连接';
  }
  return optionalServiceState.message || '浏览器直连与本地数据不受影响';
}

function paintOptionalServiceState() {
  const modal = document.getElementById(MODAL_ID);
  if (!modal?.classList.contains('open')) return;
  const label = modal.querySelector('.sd-optional-service-label');
  const detail = modal.querySelector('.sd-optional-service-detail');
  const lazyCount = modal.querySelector('.sd-lazy-feature-count');
  const lazyDetail = modal.querySelector('.sd-lazy-feature-detail');
  if (label) {
    label.textContent = optionalServiceLabel();
    label.dataset.status = optionalServiceState.status;
  }
  if (detail) detail.textContent = optionalServiceDetail();
  const lazyFeatures = featureRuntime.snapshot();
  if (lazyCount) lazyCount.textContent = `按需功能 ${lazyFeatures.filter((feature) => feature.status === 'ready').length}/${lazyFeatures.length}`;
  if (lazyDetail) lazyDetail.textContent = lazyFeatureDetail(lazyFeatures);
}

async function refreshOptionalServiceState(force = false) {
  if (optionalServiceProbePromise) return optionalServiceProbePromise;
  if (!force && optionalServiceState.checkedAt && Date.now() - optionalServiceState.checkedAt < 60000) return optionalServiceState;
  optionalServiceState = { ...optionalServiceState, status: 'checking', message: '' };
  paintOptionalServiceState();
  optionalServiceProbePromise = (async () => {
    try {
      const capabilityRuntime = await featureRuntime.load('optionalService');
      const headers = typeof ctx().getRequestHeaders === 'function' ? ctx().getRequestHeaders() : {};
      optionalServiceState = await capabilityRuntime.probeQianmuOptionalService({ headers });
    } catch (_) {
      optionalServiceState = { status: 'error', available: false, version: '', services: [], message: '增强服务检测模块暂不可用', checkedAt: Date.now() };
    } finally {
      optionalServiceProbePromise = null;
      paintOptionalServiceState();
    }
    return optionalServiceState;
  })();
  return optionalServiceProbePromise;
}

function runtimeHealthSnapshot() {
  const observers = [
    ['输入菜单', inputMenuObserver],
    ['正文排版', proseLayoutObserver],
    ['配音楼层', ttsChatObserver],
    ['伴读面板', readerPanelObserver],
    ['蜂巢归位', quickDockObserver],
    ...[...quickDockShadowObservers.keys()].map((_, index) => [`蜂巢影子根 ${index + 1}`, true]),
  ].filter(([, active]) => Boolean(active)).map(([label]) => label);
  const timers = [
    ['专注时钟', focusClockTicker],
    ['分镜正文同步', storyboardInlineTimer],
    ['配音扫描', ttsScanTimer],
    ['配音变更', ttsMutationTimer],
    ['蜂巢恢复', quickDockRestoreTimer],
    ['蜂巢重试', quickDockRetryTimer],
  ].filter(([, active]) => Boolean(active)).map(([label]) => label);
  if (notesSaveTimers.size) timers.push(`便笺保存 ${notesSaveTimers.size}`);
  const settingsBytes = storageJsonBytes(settings || {});
  const chatBytes = storageJsonBytes(ctx().chatMetadata?.[MODULE_NAME] || {});
  const renderAverageMs = performanceRuntime.modalRenderCount
    ? performanceRuntime.modalRenderTotalMs / performanceRuntime.modalRenderCount
    : 0;
  const warnings = [];
  const lazyFeatures = featureRuntime.snapshot();
  const migrationFailures = Object.entries(migrationRuntime)
    .filter(([, item]) => item.status === 'rolled_back')
    .map(([scope]) => scope === 'settings' ? '设置' : '当前聊天');
  if (settingsBytes >= 1024 * 1024) warnings.push('设置数据已超过 1 MB');
  if (chatBytes >= 1024 * 1024) warnings.push('当前聊天数据已超过 1 MB');
  if (performanceRuntime.modalRenderLastMs >= 50) warnings.push('最近一次界面重绘超过 50 ms');
  if (performanceRuntime.lastNodeCount >= 3500) warnings.push('当前千幕界面节点较多');
  if (migrationFailures.length) warnings.push(`${migrationFailures.join('、')}迁移已回退`);
  return { observers, timers, settingsBytes, chatBytes, renderAverageMs, lazyFeatures, migrationFailures, productionPackets: directorProductionPacketState.packets.length, warnings };
}

function renderRuntimeHealthCard() {
  const snapshot = runtimeHealthSnapshot();
  const status = snapshot.warnings.length ? snapshot.warnings.join('；') : '当前未发现明显压力信号';
  return `<section class="sd-card sd-runtime-health-card">
    <details class="sd-plain-fold" data-acc="runtime-health">
      <summary><b>运行与性能</b><span class="sd-summary-note">${htmlEscape(status)}</span></summary>
      <div class="sd-runtime-health-body">
        <div class="sd-runtime-health-grid">
          <span>启动初始化<b>${htmlEscape(performanceRuntime.initMs.toFixed(1))} ms</b></span>
          <span>模块至就绪<b>${htmlEscape(performanceRuntime.readyMs.toFixed(1))} ms</b></span>
          <span>最近重绘<b>${htmlEscape(performanceRuntime.modalRenderLastMs.toFixed(1))} ms</b></span>
          <span>平均重绘<b>${htmlEscape(snapshot.renderAverageMs.toFixed(1))} ms</b></span>
          <span>最慢重绘<b>${htmlEscape(performanceRuntime.modalRenderMaxMs.toFixed(1))} ms</b></span>
          <span>慢重绘<b>${htmlEscape(performanceRuntime.slowModalRenderCount)}</b></span>
          <span>界面节点<b>${htmlEscape(performanceRuntime.lastNodeCount)}</b></span>
          <span>重绘 / 打开<b>${htmlEscape(performanceRuntime.modalRenderCount)} / ${htmlEscape(performanceRuntime.modalOpenCount)}</b></span>
          <span>设置数据<b>${htmlEscape(formatStorageBytes(snapshot.settingsBytes))}</b></span>
          <span>当前聊天<b>${htmlEscape(formatStorageBytes(snapshot.chatBytes))}</b></span>
          <span>迁移保护<b>${snapshot.migrationFailures.length ? `已回退 · ${htmlEscape(snapshot.migrationFailures.join('、'))}` : '正常'}</b></span>
          <span>制片包缓存<b>${htmlEscape(snapshot.productionPackets)}</b></span>
          <span>增强服务<b class="sd-optional-service-label" data-status="${htmlEscape(optionalServiceState.status)}">${htmlEscape(optionalServiceLabel())}</b></span>
        </div>
        <p class="sd-runtime-health-line"><span>活动观察器 ${snapshot.observers.length}</span>${htmlEscape(snapshot.observers.join(' · ') || '无')}</p>
        <p class="sd-runtime-health-line"><span>活动计时器 ${snapshot.timers.length}</span>${htmlEscape(snapshot.timers.join(' · ') || '无')}</p>
        <p class="sd-runtime-health-line"><span class="sd-lazy-feature-count">按需功能 ${snapshot.lazyFeatures.filter((feature) => feature.status === 'ready').length}/${snapshot.lazyFeatures.length}</span><span class="sd-lazy-feature-detail">${htmlEscape(lazyFeatureDetail(snapshot.lazyFeatures))}</span></p>
        <p class="sd-runtime-health-line"><span>增强能力</span><span class="sd-optional-service-detail">${htmlEscape(optionalServiceDetail())}</span></p>
        <div class="sd-runtime-health-actions"><small>数据只保留在本次页面，不写入日志或用户设置。</small><button type="button" class="sd-btn sd-mini-btn sd-runtime-health-refresh">刷新诊断</button></div>
      </div>
    </details>
  </section>`;
}

function storageDiagnosticSnapshot() {
  const storyboard = settings?.imagegen || {};
  return {
    apiLogs: Array.isArray(settings?.logHistory) ? settings.logHistory : [],
    storyboardLogs: Array.isArray(storyboard.logs) ? storyboard.logs : [],
    storyboardPipelineLogs: Array.isArray(storyboard.pipelineLogs) ? storyboard.pipelineLogs : [],
  };
}

function storageSettingsSnapshotWithoutDiagnostics() {
  const storyboard = settings?.imagegen || {};
  return {
    ...settings,
    logHistory: [],
    logOpenState: {},
    imagegen: { ...storyboard, logs: [], pipelineLogs: [] },
  };
}

async function collectStorageInventory() {
  const storageApi = globalThis.navigator?.storage;
  const [originEstimate, idb, orphanReaderBlobs, imageAttempts, imageChannels, serviceReceipts] = await Promise.all([
    storageApi?.estimate?.().catch(() => null) || Promise.resolve(null),
    blobStore.estimateBlobStoreUsage(),
    blobStore.auditOrphanedReaderBlobs(),
    featureRuntime.load('imageAdmission').then(module => module.manageImageAdmissionStorage()).catch(error => ({ bytes: 0, count: 0, error: error?.message || '生图防重记录暂不可读取' })),
    storyboardManageImageChannels().catch(error => ({ bytes: 0, count: 0, error: error?.message || 'NAI 连接协调记录暂不可读取' })),
    storyboardImageServiceRuntime().then(client => client.manage()).catch(error => ({ bytes: 0, count: 0, error: error?.message || '增强生图领取记录暂不可读取' })),
  ]);
  const pressure = blobStore.classifyStoragePressure(originEstimate || {});
  const settingsBytes = storageJsonBytes(storageSettingsSnapshotWithoutDiagnostics());
  const currentChatBytes = storageJsonBytes(getChatStore());
  const diagnosticsBytes = storageJsonBytes(storageDiagnosticSnapshot());
  const currentChat = getChatStore();
  const portableTtsBytes = storageJsonBytes({
    ttsLines: currentChat.ttsLines || {},
    ttsLineKeyByMes: currentChat.ttsLineKeyByMes || {},
  });
  const categoryMap = new Map();
  const addCategory = (category, bytes, count = 0, recoverableBytes = 0) => {
    const current = categoryMap.get(category) || { category, bytes: 0, count: 0, recoverableBytes: 0 };
    current.bytes += Math.max(0, Number(bytes) || 0);
    current.count += Math.max(0, Number(count) || 0);
    current.recoverableBytes += Math.max(0, Number(recoverableBytes) || 0);
    categoryMap.set(category, current);
  };
  for (const item of idb.categories || []) addCategory(item.category, item.bytes, item.count, item.recoverableBytes);
  addCategory('settings', settingsBytes, 1, 0);
  addCategory('chat', currentChatBytes, 1, 0);
  addCategory('logs', diagnosticsBytes, 0, diagnosticsBytes);
  addCategory('logs', imageAttempts.bytes, imageAttempts.count);
  addCategory('logs', imageChannels.bytes, imageChannels.count);
  addCategory('logs', serviceReceipts.bytes, serviceReceipts.count);
  const trackedBytes = Number(idb.totalBytes || 0) + settingsBytes + currentChatBytes + diagnosticsBytes + imageAttempts.bytes + imageChannels.bytes + serviceReceipts.bytes;
  const recoverableBytes = Number(idb.recoverableBytes || 0) + diagnosticsBytes;
  const manageableBytes = Number(idb.totalBytes || 0) + diagnosticsBytes + portableTtsBytes + imageAttempts.bytes + imageChannels.bytes + serviceReceipts.bytes;
  return {
    sampledAt: Date.now(),
    origin: {
      usage: Math.max(0, Number(originEstimate?.usage) || 0),
      quota: Math.max(0, Number(originEstimate?.quota) || 0),
      persisted: false,
      available: Boolean(originEstimate),
      pressure,
    },
    idb,
    categories: [...categoryMap.values()].sort((a, b) => b.bytes - a.bytes),
    trackedBytes,
    recoverableBytes,
    diagnosticsBytes,
    portableTtsBytes,
    manageableBytes,
    orphanReaderBlobs,
    imageAttempts,
    imageChannels,
    serviceReceipts,
  };
}

async function refreshStorageInventory(force = false) {
  if (storageInventoryState.status === 'loading') return storageInventoryState.data;
  if (!force && storageInventoryState.data && Date.now() - storageInventoryState.sampledAt < 30000) return storageInventoryState.data;
  storageInventoryState = { ...storageInventoryState, status: 'loading', error: '' };
  paintStorageManagementCard();
  try {
    const data = await collectStorageInventory();
    storageInventoryState = { status: 'ready', data, error: '', sampledAt: data.sampledAt };
  } catch (error) {
    storageInventoryState = { ...storageInventoryState, status: 'error', error: error?.message || String(error), sampledAt: Date.now() };
  }
  paintStorageManagementCard();
  return storageInventoryState.data;
}

const STORAGE_CATEGORY_LABELS = Object.freeze({
  images: '图片', audio: '音频', video: '动态影片', reader: '伴读资料', notes: '固定便笺', logs: '日志', cache: '临时缓存', settings: '设置与预设', chat: '当前聊天数据', other: '其他',
});

const STORAGE_CATEGORY_COLORS = Object.freeze({
  images: '#5aa9ff', audio: '#ff9f43', video: '#6f8fff', reader: '#9b7cff', notes: '#f2c94c', logs: '#ff647c', cache: '#3dc7c9', settings: '#65c466', chat: '#8d94a6', other: '#747b88',
});

function renderStorageManagementCard() {
  const { status, data, error } = storageInventoryState;
  if (!data) {
    const message = status === 'error' ? `盘点失败：${htmlEscape(error || '当前环境不可用')}` : '正在盘点本机数据…';
    return `<section class="sd-card sd-storage-card"><div class="sd-card-title-row"><h3>储存空间</h3><button type="button" class="sd-icon-btn sd-storage-refresh" title="刷新" aria-label="刷新"><i class="fa-solid fa-rotate"></i></button></div><p class="sd-muted">${message}</p></section>`;
  }
  const categories = data.categories.filter((item) => Number(item.bytes) > 0);
  const originUsage = Math.max(0, Number(data.origin.usage) || 0);
  const knownUsage = Math.max(0, Number(data.trackedBytes) || 0);
  const unknownUsage = Math.max(0, originUsage - knownUsage);
  const usedForScale = Math.max(originUsage, knownUsage);
  const freeBytes = data.origin.quota > 0 ? Math.max(0, data.origin.quota - usedForScale) : 0;
  const scaleBytes = Math.max(1, data.origin.quota > 0 ? Math.max(data.origin.quota, usedForScale) : usedForScale);
  const barItems = [
    ...categories.map((item) => ({ key: item.category, label: STORAGE_CATEGORY_LABELS[item.category] || item.category, bytes: Number(item.bytes) || 0, color: STORAGE_CATEGORY_COLORS[item.category] || STORAGE_CATEGORY_COLORS.other })),
    ...(unknownUsage > 0 ? [{ key: 'origin-other', label: '其他 ST 数据', bytes: unknownUsage, color: '#555d6b' }] : []),
    ...(freeBytes > 0 ? [{ key: 'free', label: '可用空间', bytes: freeBytes, color: 'rgba(127, 127, 127, .18)' }] : []),
  ];
  const storageBar = barItems.map((item) => `<i class="sd-storage-segment sd-storage-${htmlEscape(item.key)}" style="--sd-storage-weight:${Math.max(0, item.bytes / scaleBytes)};--sd-storage-color:${item.color}" title="${htmlEscape(item.label)} ${htmlEscape(formatStorageBytes(item.bytes))}"></i>`).join('');
  const legend = barItems.map((item) => `<span><i style="--sd-storage-color:${item.color}"></i><em>${htmlEscape(item.label)}</em><b>${htmlEscape(formatStorageBytes(item.bytes))}</b></span>`).join('');
  const originText = data.origin.available
    ? `${formatStorageBytes(data.origin.usage)} / ${formatStorageBytes(data.origin.quota)}`
    : '浏览器未提供配额信息';
  const orphanCount = Math.max(0, Number(data.orphanReaderBlobs?.count) || 0);
  const orphanText = orphanCount
    ? `${orphanCount} 项 · ${formatStorageBytes(data.orphanReaderBlobs?.bytes)}`
    : '未发现';
  const pressure = data.origin.pressure || blobStore.classifyStoragePressure(data.origin);
  const pressurePercent = Math.min(999, Math.max(0, Math.round(Number(pressure.ratio || 0) * 100)));
  const pressureNotice = pressure.level === 'critical'
    ? `<p class="sd-storage-pressure is-critical" role="status">浏览器来源空间已使用 ${pressurePercent}% · 剩余约 ${htmlEscape(formatStorageBytes(pressure.freeBytes))}。建议先备份再按模块整理；千幕不会自动清理。</p>`
    : pressure.level === 'warning'
      ? `<p class="sd-storage-pressure is-warning" role="status">浏览器来源空间已使用 ${pressurePercent}% · 剩余约 ${htmlEscape(formatStorageBytes(pressure.freeBytes))}。可按需整理，千幕不会自动清理。</p>`
      : '';
  return `<section class="sd-card sd-storage-card">
    <div class="sd-card-title-row"><div><h3>储存空间</h3><p class="sd-summary-note">${htmlEscape(new Date(data.sampledAt).toLocaleTimeString())}</p></div><button type="button" class="sd-icon-btn sd-storage-refresh" title="刷新" aria-label="刷新"><i class="fa-solid fa-rotate${status === 'loading' ? ' fa-spin' : ''}"></i></button></div>
    <div class="sd-storage-totals"><span>浏览器 / ST 来源<b>${htmlEscape(originText)}</b></span><span>千幕已盘点<b>${htmlEscape(formatStorageBytes(data.trackedBytes))}</b></span><span>可管理项目<b>${htmlEscape(formatStorageBytes(data.manageableBytes))}</b></span><span>孤儿图片<b>${htmlEscape(orphanText)}</b></span></div>
    <div class="sd-storage-ios-bar" role="img" aria-label="储存空间分布">${storageBar}</div>
    <div class="sd-storage-legend">${legend || '<p class="sd-muted">暂未发现千幕本地数据。</p>'}</div>
    ${pressureNotice}
    ${data.imageAttempts?.error ? `<p class="sd-storage-pressure is-warning">${htmlEscape(data.imageAttempts.error)}</p>` : ''}
    ${data.imageChannels?.error ? `<p class="sd-storage-pressure is-warning">${htmlEscape(data.imageChannels.error)}</p>` : ''}
    ${data.serviceReceipts?.error ? `<p class="sd-storage-pressure is-warning">${htmlEscape(data.serviceReceipts.error)}</p>` : ''}
    <p class="sd-storage-scope">此处是浏览器分配给当前 ST 站点来源的空间，不代表 VPS 磁盘总容量；千幕仅统计可明确归因的本地内容。</p>
    <div class="sd-storage-actions"><button type="button" class="sd-btn sd-primary sd-storage-clean" ${data.manageableBytes > 0 ? '' : 'disabled'}><i class="fa-solid fa-sliders"></i>选择清理模块</button><button type="button" class="sd-btn sd-storage-chat-clean" ${data.idb?.chatScopes?.length ? '' : 'disabled'}><i class="fa-solid fa-message"></i>按聊天管理</button></div>
  </section>`;
}

