const STORYBOARD_NAI_NEGATIVE_DEFAULTS = Object.freeze({
  'nai-diffusion-5-full': 'lowres, artistic error, film grain, scan artifacts, worst quality, bad quality, jpeg artifacts, very displeasing, chromatic aberration, dithering, halftone, screentone, multiple views, logo, too many watermarks, negative space, blank page',
  'nai-diffusion-5-curated': 'lowres, artistic error, film grain, scan artifacts, worst quality, bad quality, jpeg artifacts, very displeasing, chromatic aberration, dithering, halftone, screentone, multiple views, logo, too many watermarks, negative space, blank page',
  'nai-diffusion-4-5-full': 'lowres, artistic error, film grain, scan artifacts, worst quality, bad quality, jpeg artifacts, very displeasing, chromatic aberration, dithering, halftone, screentone, multiple views, logo, too many watermarks, negative space, blank page',
  'nai-diffusion-4-5-curated': 'blurry, lowres, upscaled, artistic error, film grain, scan artifacts, worst quality, bad quality, jpeg artifacts, very displeasing, chromatic aberration, halftone, multiple views, logo, too many watermarks, negative space, blank page',
  'nai-diffusion-4-full': 'blurry, lowres, error, film grain, scan artifacts, worst quality, bad quality, jpeg artifacts, very displeasing, chromatic aberration, multiple views, logo, too many watermarks, white blank page, blank page',
  'nai-diffusion-4-curated-preview': 'blurry, lowres, error, film grain, scan artifacts, worst quality, bad quality, jpeg artifacts, very displeasing, chromatic aberration, logo, dated, signature, multiple views, white blank page, blank page',
  'nai-diffusion-3': 'lowres, bad anatomy, bad hands, text, error, missing fingers, extra digit, fewer digits, cropped, worst quality, low quality, normal quality, jpeg artifacts, signature, watermark, username, blurry',
});

function storyboardPromptDefaultsKey(sourceId, modelId) {
  return `${String(sourceId || '')}:${String(modelId || '')}`.slice(0, 500);
}

function storyboardProviderPromptDefaults(sourceId, modelId, state = storyboardState(), capabilityModelId = '') {
  const capabilityId = resolveStoryboardModelBinding(sourceId, { model: modelId, capabilityModelId }).capabilityModelId;
  const builtin = sourceId === 'comfy' ? { positive: '', negative: '' } : sourceId !== 'novel' ? STORYBOARD_GENERIC_PROMPT_DEFAULTS : {
    positive: STORYBOARD_NAI_QUALITY_DEFAULTS[capabilityId] || STORYBOARD_NAI_QUALITY_DEFAULTS['nai-diffusion-5-full'],
    negative: STORYBOARD_NAI_NEGATIVE_DEFAULTS[capabilityId] || STORYBOARD_NAI_NEGATIVE_DEFAULTS['nai-diffusion-5-full'],
  };
  const remembered = state?.promptDefaults?.[storyboardPromptDefaultsKey(sourceId, modelId)] || {};
  return {
    positive: String(Object.hasOwn(remembered, 'positive') ? remembered.positive : builtin.positive || '').trim(),
    negative: String(Object.hasOwn(remembered, 'negative') ? remembered.negative : builtin.negative || '').trim(),
  };
}

function storyboardSelectedArtistPreset(state) {
  return state.artistPresets.find((item) => item.id === state.selectedArtistPresetId) || null;
}

function storyboardJoinPrompt(parts, sourceId) {
  const values = uniqueClean(parts.map((item) => String(item || '').trim()).filter(Boolean));
  return values.join(sourceId === 'novel' ? ', ' : '\n\n');
}

function storyboardPromptLayerForArtist(state, artist, sourceId, modelId, capabilityModelId = '') {
  const defaults = storyboardProviderPromptDefaults(sourceId, modelId, state, capabilityModelId);
  if (!getStoryboardCapabilities(sourceId, capabilityModelId || modelId).supportsArtistSyntax) artist = null;
  return {
    positive: String(artist?.positivePrompt || defaults.positive || '').trim(),
    negative: String(artist?.negativePrompt || defaults.negative || '').trim(),
    defaults,
  };
}

function storyboardRememberPromptLayer(state, artist, sourceId, modelId, field, value) {
  const normalized = String(value || '').trim().slice(0, 12000);
  if (artist && getStoryboardCapabilities(sourceId).supportsArtistSyntax) {
    artist[field === 'positive' ? 'positivePrompt' : 'negativePrompt'] = normalized;
    artist.updatedAt = Date.now();
    return;
  }
  state.promptDefaults ||= {};
  const key = storyboardPromptDefaultsKey(sourceId, modelId);
  const current = { ...(state.promptDefaults[key] || {}) };
  current[field] = normalized;
  state.promptDefaults[key] = current;
}

function storyboardPromptsForArtist(state, artist, sourceId, modelId, { prompt = state.prompt, negative = state.negative, honorBaked = true, fallbackToStateArtist = true, capabilityModelId = '' } = {}) {
  const layer = storyboardPromptLayerForArtist(state, artist, sourceId, modelId, capabilityModelId);
  const artistString = getStoryboardCapabilities(sourceId, capabilityModelId || modelId).supportsArtistSyntax
    ? String(artist?.value ?? (fallbackToStateArtist ? state.promptDraft?.artistString : '') ?? '').trim() : '';
  return {
    prompt: honorBaked && state.promptDraft?.artistPositiveBaked
      ? String(prompt || '').trim()
      : storyboardJoinPrompt([artistString, layer.positive, prompt], sourceId),
    negative: honorBaked && state.promptDraft?.artistNegativeBaked
      ? String(negative || '').trim()
      : storyboardJoinPrompt([layer.negative, negative], sourceId),
    artistString,
  };
}

function storyboardRemovePromptLayer(value, layer) {
  const source = String(value || '').trim();
  const needle = String(layer || '').trim();
  if (!source || !needle) return source;
  return source.replace(needle, '').replace(/(?:\s*,\s*){2,}/g, ', ').replace(/^[\s,]+|[\s,]+$/g, '').replace(/\n{3,}/g, '\n\n').trim();
}

function storyboardBasePromptsForArtistRedraw(record, snapshot) {
  const state = storyboardState();
  const identity = resolveStoryboardJobModelIdentity(snapshot);
  const sourceId = identity.modelFamily;
  const modelId = identity.remoteModelId;
  const capabilityModelId = identity.capabilityModelId;
  if (!getStoryboardCapabilities(sourceId, capabilityModelId).supportsArtistSyntax) {
    const error = new Error('此模型不使用 NAI 画师串，请编辑画面要求后重绘'); error.code = 'artist_syntax_unsupported'; throw error;
  }
  const oldArtist = state.artistPresets.find((item) => item.id === record.artistPresetId)
    || state.artistPresets.find((item) => item.value === record.artistString) || null;
  const defaults = storyboardProviderPromptDefaults(sourceId, modelId, state, capabilityModelId);
  let prompt = String(record.finalPrompt || snapshot.payload?.prompt || record.prompt || snapshot.prompt || '').trim();
  let negative = String(snapshot.payload?.negative ?? record.effectiveNegative ?? record.negative ?? snapshot.negative ?? '').trim();
  const oldArtistString = record.artistString || snapshot.artistString;
  if (oldArtistString) prompt = storyboardRemovePromptLayer(prompt, oldArtistString);
  prompt = storyboardRemovePromptLayer(prompt, oldArtist?.positivePrompt || defaults.positive);
  negative = storyboardRemovePromptLayer(negative, oldArtist?.negativePrompt || defaults.negative);
  return { prompt: prompt || String(record.prompt || snapshot.prompt || '').trim(), negative, sourceId, modelId, capabilityModelId };
}

function storyboardPageKey(state = storyboardState()) {
  if (state.view === 'create' && state.source === 'comfy') return 'create:comfy';
  if (state.editingArtistPresetId) return `artists:edit:${state.editingArtistPresetId}`;
  if (state.editingPromptItemId) return `presets:item:${state.editingPromptItemId}`;
  if (state.view === 'assets') return `assets:${state.assetView || 'tags'}`;
  return String(state.view || 'create');
}

function storyboardScroller(root = document) {
  return root?.querySelector?.('.sd-storyboard-scroll') || document.querySelector('#story-director-modal .sd-storyboard-scroll');
}

function storyboardRememberPageScroll(root = document) {
  const scroller = storyboardScroller(root);
  if (scroller) storyboardPageScrolls.set(storyboardPageKey(), Math.max(0, scroller.scrollTop || 0));
}

function storyboardApplyRoute(entry = {}) {
  const state = storyboardState();
  for (const key of ['view', 'assetView', 'assetSearch', 'artistSearch', 'artistCollectionId', 'editingArtistPresetId', 'editingPromptPresetId', 'editingPromptItemId', 'gallerySearch', 'gallerySource']) {
    if (entry[key] !== undefined) state[key] = entry[key];
  }
  if (Object.hasOwn(entry, 'promptItemDraft')) state.promptItemDraft = entry.promptItemDraft ? clone(entry.promptItemDraft) : null;
  if (Object.hasOwn(entry, 'galleryCollectionId')) storyboardGalleryOpenCollectionId = String(entry.galleryCollectionId || '');
  if (Object.hasOwn(entry, 'galleryInspectorId')) storyboardGalleryInspectorRecordId = String(entry.galleryInspectorId || '');
  if (Object.hasOwn(entry, 'galleryVisibleCount')) storyboardGalleryVisibleCount = Math.max(40, Number(entry.galleryVisibleCount) || 40);
}

function storyboardBeginSession() {
  storyboardPendingRestoreScroll = storyboardPageScrolls.get(storyboardPageKey()) || 0;
}

function storyboardEndSession() {
  if (typeof document !== 'undefined') document.getElementById(MODAL_ID)?._sdComfyReadinessCleanup?.();
  if (typeof document !== 'undefined') document.getElementById(MODAL_ID)?._sdComfyTargetsCleanup?.();
  storyboardComfyLibraryController?.detach();
  storyboardPendingRestoreScroll = null;
  storyboardPresetUndo = null;
  clearTimeout(storyboardPresetUndoTimer);
  storyboardPresetUndoTimer = null;
}

function storyboardNavigate(root, patch = {}) {
  storyboardRememberPageScroll(root);
  storyboardApplyRoute(patch);
  storyboardPendingRestoreScroll = storyboardPageScrolls.get(storyboardPageKey()) || 0;
  saveSettings();
  renderModal();
}

function storyboardReturnTo(root, view, patch = {}) {
  storyboardRememberPageScroll(root);
  storyboardApplyRoute({ view, ...patch });
  storyboardPendingRestoreScroll = storyboardPageScrolls.get(storyboardPageKey()) || 0;
  storyboardCloseLightbox();
  saveSettings();
  renderModal();
}

function storyboardPageTitle(state) {
  // Read only: opening a title must never normalize settings or discard an editor draft.
  if (state.view === 'create' && state.source === 'comfy') return 'COMFY WORKBENCH';
  if (state.view === 'workflows') return 'WORKFLOW LIBRARY';
  if (state.view === 'artists') {
    const editing = state.editingArtistPresetId === 'new' || state.artistPresets?.some((item) => item.id === state.editingArtistPresetId);
    return editing ? 'ARTIST PROFILE' : 'ARTIST LIBRARY';
  }
  if (state.view === 'presets') {
    const preset = state.promptPresets?.find((item) => item.id === state.promptCompiler?.instructionPresetId);
    return preset && state.editingPromptItemId ? 'FRAMING ENTRY' : 'FRAMING PRESETS';
  }
  if (state.view === 'assets') return ({ tags: 'TAG LIBRARY', vibes: 'VIBE LIBRARY', routing: 'SHOT GROUPS' })[state.assetView] || 'TAG LIBRARY';
  // Character route is reserved for ST2-07; do not expose an empty navigation entry yet.
  return ({ create: 'STORYBOARD', characters: 'CHARACTERS', gallery: 'SCREENING ROOM', logs: 'LOGS' })[state.view] || 'STORYBOARD';
}

function renderStoryboardNav(state) {
  const selected = state.view === 'workflows' ? 'create' : state.view;
  const items = [
    ['create', '镜头台', 'fa-camera', 'qm-regular-aperture'],
    ['assets', '素材库', 'fa-tags', 'qm-duotone-tag'],
    ['gallery', '阅片室', 'fa-images', 'screening'],
    ['logs', '日志', 'fa-list-ul', 'qm-regular-list-bullets'],
  ];
  return `<nav class="sd-storyboard-nav" aria-label="分镜功能">${items.map(([id, label, icon, glyph]) => `<button type="button" aria-current="${selected === id ? 'page' : 'false'}" aria-label="${label}" class="${selected === id ? 'active' : ''}" data-storyboard-view="${id}"><i class="fa-solid ${icon}" data-qm-icon="${glyph}"></i><span>${label}</span></button>`).join('')}</nav>`;
}

function storyboardConnectionState(state, providerId = state.source) {
  const group = state.connections[providerId];
  const active = group?.presets?.find((item) => item.id === group.activePresetId) || null;
  return { group, active, draft: group?.draft || active || {} };
}

function renderStoryboardModelPicker(providerId, selected, capabilityModelId = '', route = false) {
  const id = uid('model-picker');
  return `<div class="sd-model-picker" data-storyboard-model-picker="${providerId}" data-route="${route}">
    <div class="sd-model-picker-input-row"><input id="${id}" class="text_pole ${route ? 'sd-storyboard-route-model' : 'sd-storyboard-model-select'}" role="combobox" aria-label="模型：可搜索或填写完整 ID" aria-autocomplete="list" aria-expanded="false" autocomplete="off" spellcheck="false" maxlength="240" value="${htmlEscape(selected)}"><button type="button" class="sd-icon-btn sd-model-picker-pull" title="拉取模型（只读）" aria-label="拉取模型" ${providerId === 'comfy' ? 'disabled' : ''}><i class="fa-solid fa-rotate"></i></button></div>
    <div class="sd-model-picker-panel" hidden></div>
  </div>`;
}

function storyboardApplyModelBinding(root, state, providerId, binding, rule = null) {
  if (!root.isConnected || state !== storyboardState()) return false;
  binding = resolveStoryboardModelBinding(providerId, binding);
  if (rule) {
    if (!state.routing.rules.includes(rule) || rule.target.providerId !== providerId) return false;
    Object.assign(rule.target, { modelId: binding.remoteModelId, capabilityModelId: binding.capabilityModelId, parameterPresetId: '' });
  } else {
    if (state.source !== providerId) return false;
    const previousModel = String(state.profiles[providerId]?.model || STORYBOARD_PROVIDER_REGISTRY[providerId]?.defaultModel || '');
    storyboardCaptureWorkbench(root, providerId, { rememberModel: false });
    state.modelProfiles ||= {};
    const captured = clone(state.profiles[providerId]);
    if (previousModel) rememberStoryboardModelProfile(state.modelProfiles, providerId, { ...captured, model: previousModel });
    const remembered = getStoryboardRememberedProfile(state.modelProfiles, providerId, binding.remoteModelId, binding.capabilityModelId);
    state.profiles[providerId] = remembered
      ? { ...clone(remembered), model: binding.remoteModelId, capabilityModelId: binding.capabilityModelId, loaded: true }
      : { ...createStoryboardDefaults().profiles[providerId], model: binding.remoteModelId, capabilityModelId: binding.capabilityModelId, loaded: false };
    rememberStoryboardModelProfile(state.modelProfiles, providerId, state.profiles[providerId]);
    state.parameterPresetSelection[providerId] = '';
  }
  saveSettings(); renderModal(); return true;
}

function bindStoryboardModelPicker(root, host, state) {
  const providerId = host.dataset.storyboardModelPicker;
  const row = host.closest('[data-storyboard-route-rule]');
  const rule = row ? state.routing.rules.find((item) => item.id === row.dataset.storyboardRouteRule) : null;
  if (row && !rule) return;
  let loading = null, instance = null;
  const ensure = () => {
    if (instance && !instance.isCurrent()) { instance.dispose(); instance = null; loading = null; }
    return loading ||= (async () => {
    if (!host.isConnected || state !== storyboardState()) return null;
    if (!rule) storyboardCaptureWorkbench(root);
    const read = () => {
      const group = storyboardConnectionState(state, providerId);
      const connection = rule?.target.connectionPresetId
        ? group.group.presets.find((item) => item.id === rule.target.connectionPresetId) : group.draft;
      return { connection, preset: rule?.target.connectionPresetId || group.group.activePresetId,
        keyRevision: storyboardCredentialRevision, draftKey: rule?.target.connectionPresetId ? '' : storyboardDraftApiKeys.get(providerId),
        model: rule?.target.modelId || state.profiles[providerId]?.model, capability: rule?.target.capabilityModelId || state.profiles[providerId]?.capabilityModelId,
        source: rule?.target.providerId || state.source,
        // Include live unsaved fields too: a quick click must not beat the workbench's debounced save.
        fields: rule ? [] : [...root.querySelectorAll('.sd-comfy-transport, .sd-storyboard-private-network, .sd-storyboard-protocol, .sd-storyboard-base-url, .sd-storyboard-api-key-memory, .sd-storyboard-openai-compat input, .sd-storyboard-openai-compat textarea, .sd-storyboard-openai-compat select')].map((field) => [field.value, field.checked]) };
    };
    // Ephemeral comparison only; never use connection credentials as a cache key or persist this snapshot.
    const initial = read(), snapshot = JSON.stringify(initial), chatKey = getChatKey();
    const isCurrent = () => host.isConnected && state === storyboardState() && chatKey === getChatKey()
      && (!rule || state.routing.rules.includes(rule)) && snapshot === JSON.stringify(read());
    const runtime = await featureRuntime.load('modelPicker');
    if (!isCurrent()) { loading = null; return null; }
    const profile = rule ? { model: rule.target.modelId, capabilityModelId: rule.target.capabilityModelId } : storyboardProviderProfile(state, providerId);
    return instance = runtime.attachModelPicker(host, {
      provider: providerId, models: STORYBOARD_MODEL_REGISTRY[providerId], current: profile, isCurrent,
      apply: (selection) => {
        const binding = resolveStoryboardModelBinding(providerId, selection);
        if (providerId === 'comfy' && binding.remoteModelId !== 'comfy-workflow') throw new Error('ComfyUI 模型请在 API Workflow 中设置');
        return storyboardApplyModelBinding(root, state, providerId, binding, rule);
      },
      fetchModels: async () => {
        if (!initial.connection) throw new Error('API 预设已失效，请重新选择');
        const connection = clone(initial.connection);
        if (rule?.target.connectionPresetId && !connection.credentialId) throw new Error('API 预设没有凭据引用，请重新保存连接');
        const apiKey = initial.draftKey || await storyboardResolveApiKey(providerId, connection.credentialId);
        if (!isCurrent()) throw new Error('模型或连接已变化，请重新打开模型选择');
        const request = { provider: providerId, baseUrl: connection.baseUrl || STORYBOARD_PROVIDER_REGISTRY[providerId].defaultBaseUrl,
          ...resolveStoryboardConnectionBinding(providerId, connection),
          apiKey, allowPrivateNetwork: Boolean(connection.options?.allowPrivateNetwork), compatibility: connection.compatibility, customHeaders: connection.headers };
        if (request.imageProtocolVersion) request.baseUrl = connection.baseUrl || '';
        const comfyTransport = providerId === 'comfy' ? requireStoryboardComfyTransport(connection) : 'legacy-auto';
        if (comfyTransport !== 'gateway') {
          const direct = await directImageRuntime();
          if (!isCurrent()) throw new Error('模型或连接已变化，请重新打开模型选择');
          try { return await direct.listDirectImageModels(request); }
          catch (error) { if (comfyTransport === 'browser' || !direct.isDirectImageTransportError(error) || !isCurrent()) throw error; }
        }
        await storyboardConfirmGatewayProtocolBinding(request);
        if (!isCurrent()) throw new Error('模型或连接已变化，请重新打开模型选择');
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 20_000);
        try {
          const response = await fetch('/api/plugins/qianmu-tts/image/models', { method: 'POST', headers: storyboardRequestHeaders(),
            body: JSON.stringify(request), signal: controller.signal, credentials: 'same-origin', redirect: 'error', cache: 'no-store' });
          const data = await response.json().catch(() => ({}));
          if (!response.ok || !data.ok) { const error = new Error('模型列表读取失败'); error.status = response.status; error.code = data.code || ''; throw error; }
          return data;
        } finally { clearTimeout(timer); }
      },
      errorMessage: (error) => error?.status === 401 || error?.status === 403 ? '模型列表无权限；请检查 Key，当前 Key 已保留'
        : error?.status === 404 || error?.status === 405 ? '此连接没有可用模型列表；仍可手动填写，不代表生图失败'
          : error?.code === 'missing_api_key' ? '请先填写 API Key'
            : '模型列表暂不可用；仍可手动填写模型 ID，当前设置已保留',
    });
  })().catch(() => { loading = null; if (host.isConnected) toast('模型选择暂未载入，请重试', 'warning'); return null; });
  };
  host.addEventListener('focusin', (event) => { if (event.target.matches?.('[role="combobox"]')) void ensure().then((picker) => picker?.open()); });
  host.querySelector('.sd-model-picker-pull')?.addEventListener('click', () => { void ensure().then((picker) => picker?.fetch()); });
}

function storyboardProviderProfile(state, providerId = state.source, profileOverride = null) {
  const legacy = profileOverride || state.profiles[providerId];
  const { draft } = storyboardConnectionState(state, providerId);
  const provider = STORYBOARD_PROVIDER_REGISTRY[providerId];
  let binding;
  try { binding = resolveStoryboardProfileBinding(providerId, legacy); resolveStoryboardConnectionBinding(providerId, draft); }
  catch (error) {
    return { ...legacy, model: String(legacy.model || ''), modelBindingError: error.message,
      baseUrl: String(draft.baseUrl || provider?.defaultBaseUrl || ''),
      connectionPresetId: String(storyboardConnectionState(state, providerId).group?.activePresetId || '') };
  }
  const modelDefaults = providerId === 'novel' ? getStoryboardNovelParameterSpec(binding.capabilityModelId).defaults : {};
  const resolved = { ...legacy };
  for (const [key, value] of Object.entries(modelDefaults)) {
    if (!legacy.loaded || resolved[key] === '' || resolved[key] == null) resolved[key] = value;
  }
  return {
    ...resolved,
    model: binding.remoteModelId,
    capabilityModelId: binding.capabilityModelId,
    baseUrl: String(draft.protocol && draft.protocol !== provider.protocol ? (draft.baseUrl || '') : (draft.baseUrl || provider.defaultBaseUrl || '')),
    connectionPresetId: String(storyboardConnectionState(state, providerId).group?.activePresetId || ''),
  };
}

function renderStoryboardConnectionCompatibility(state) {
  const connection = storyboardConnectionState(state).draft;
  if (state.source === 'openai') return renderStoryboardOpenAICompatibility(connection);
  if (!['banana', 'seedream'].includes(state.source)) return '';
  const native = STORYBOARD_PROVIDER_REGISTRY[state.source].protocol;
  const selected = connection.protocol || native;
  return `<details class="sd-storyboard-connection-compat" ${selected !== native ? 'open' : ''}>
    <summary><span>连接兼容</span></summary><div class="sd-storyboard-openai-compat-body">
      <label><span>接口格式</span><select class="text_pole sd-storyboard-protocol" aria-label="接口格式"><option value="${native}" ${selected === native ? 'selected' : ''}>原生接口</option><option value="openai-images" ${selected === 'openai-images' ? 'selected' : ''}>OpenAI Images 兼容</option>${![native, 'openai-images'].includes(selected) ? '<option value="invalid" selected>请选择有效接口</option>' : ''}</select></label>
      ${selected === 'openai-images' ? renderStoryboardOpenAICompatibility(connection) : ''}
    </div></details>`;
}

function renderStoryboardOpenAICompatibility(connection) {
  const compatibility = normalizeOpenAIImageCompatibility(connection?.compatibility);
  const responses = new Set(compatibility.responseKinds);
  const parameters = new Set(compatibility.allowedParameters);
  const optionKeys = (compatibility.providerOptionKeys || []).join(', ');
  const customHeaders = serializeOpenAICompatibleHeaders(connection?.headers, compatibility);
  const responseLabels = { b64_json: 'b64_json', base64: 'base64', url: 'URL' };
  const parameterLabels = { n: '多图 n', size: '尺寸', quality: '质量', background: '背景', output_format: '格式' };
  return `<details class="sd-storyboard-openai-compat">
    <summary><span>兼容能力</span><small>第三方端点按需调整</small></summary>
    <div class="sd-storyboard-openai-compat-body">
      <div class="sd-storyboard-grid sd-storyboard-grid-two">
        <label><span>生成端点</span><input class="text_pole sd-storyboard-openai-generation-endpoint" value="${htmlEscape(compatibility.endpoints.generation)}" spellcheck="false"></label>
        <label><span>编辑端点</span><input class="text_pole sd-storyboard-openai-edit-endpoint" value="${htmlEscape(compatibility.endpoints.edit)}" spellcheck="false"></label>
        <label><span>模型列表</span><select class="text_pole sd-storyboard-openai-model-discovery"><option value="optional" ${compatibility.modelDiscovery === 'optional' ? 'selected' : ''}>可选探测</option><option value="off" ${compatibility.modelDiscovery === 'off' ? 'selected' : ''}>不探测</option><option value="required" ${compatibility.modelDiscovery === 'required' ? 'selected' : ''}>必须可用</option></select></label>
        <label><span>参考图字段</span><select class="text_pole sd-storyboard-openai-reference-field"><option value="image[]" ${compatibility.referenceField === 'image[]' ? 'selected' : ''}>image[] · 多图</option><option value="image" ${compatibility.referenceField === 'image' ? 'selected' : ''}>image · 单图</option></select></label>
      </div>
      <label><span>模型列表端点</span><input class="text_pole sd-storyboard-openai-models-endpoint" value="${htmlEscape(compatibility.endpoints.models)}" spellcheck="false"></label>
      <div><span>可接收返回</span><div class="sd-storyboard-openai-capability-chips">${['b64_json', 'base64', 'url'].map((kind) => `<label class="sd-option-chip"><input type="checkbox" class="sd-storyboard-openai-response-kind" value="${kind}" ${responses.has(kind) ? 'checked' : ''}><span>${responseLabels[kind]}</span></label>`).join('')}</div></div>
      <div><span>可发送参数</span><div class="sd-storyboard-openai-capability-chips">${['n', 'size', 'quality', 'background', 'output_format'].map((key) => `<label class="sd-option-chip"><input type="checkbox" class="sd-storyboard-openai-parameter" value="${key}" ${parameters.has(key) ? 'checked' : ''}><span>${parameterLabels[key]}</span></label>`).join('')}</div></div>
      <label><span>额外字段白名单</span><input class="text_pole sd-storyboard-openai-provider-options" value="${htmlEscape(optionKeys)}" spellcheck="false"></label>
      <label><span>自定义请求头</span><textarea class="text_pole sd-storyboard-openai-headers" spellcheck="false">${htmlEscape(customHeaders)}</textarea></label>
    </div>
  </details>`;
}

function storyboardCompilerProfileOptions(state) {
  return (settings.apiProfiles || []).map((item) => `<option value="${htmlEscape(item.id)}" ${state.promptCompiler.apiProfileId === item.id ? 'selected' : ''}>${htmlEscape(item.name || item.model || '未命名预设')}</option>`).join('');
}

function storyboardComfyOutputOptions(profile) {
  let entries = [];
  try { entries = Object.entries(storyboardParseWorkflow(profile.comfyWorkflow)); } catch (_) { /* Preserve selection while editing invalid JSON. */ }
  const selected = String(profile.comfyOutputNodeId || '');
  if (selected && !entries.some(([id]) => id === selected)) entries.unshift([selected, { class_type: '节点已缺失' }]);
  const option = ([id,node]) => `<option value="${htmlEscape(id)}" ${id === selected ? 'selected' : ''}>${htmlEscape(`${id} · ${node?.class_type || '无效节点'}`)}</option>`;
  const saved = entries.filter(([,node]) => node?.class_type === 'SaveImage').map(option).join('');
  const other = entries.filter(([id,node]) => node?.class_type !== 'SaveImage' && (id === selected || node?.class_type && node.class_type !== 'PreviewImage')).map(option).join('');
  return `<option value="">全部保存节点</option>${saved ? `<optgroup label="最终保存节点">${saved}</optgroup>` : ''}${other ? `<optgroup label="其他节点（需核查输出）">${other}</optgroup>` : ''}`;
}

function renderStoryboardModelCard(state) {
  const provider = STORYBOARD_PROVIDER_REGISTRY[state.source];
  const profile = storyboardProviderProfile(state);
  const connection = storyboardConnectionState(state);
  const check = storyboardConnectionStatus.get(state.source);
  const channelPresets = connection.group?.presets || [];
  const activePreset = channelPresets.some((item) => item.id === connection.active?.id) ? connection.active.id : '';
  const presetOptions = channelPresets.map((item) => `<option value="${htmlEscape(item.id)}" ${activePreset === item.id ? 'selected' : ''}>${htmlEscape(item.name)}</option>`).join('');
  return `<details class="sd-card sd-storyboard-model-card" data-storyboard-card="model" ${state.collapsedCards.model ? '' : 'open'}>
    <summary><span><b>${state.source === 'comfy' ? '连接' : 'API 设置'}</b></span><em>${htmlEscape(provider.label)}</em></summary>
    <div class="sd-storyboard-card-body">
      <label><span>取景整理 API</span><select class="text_pole sd-storyboard-compiler-api"><option value="">沿用千幕当前 API</option>${storyboardCompilerProfileOptions(state)}</select></label>
      ${state.source !== 'comfy' ? `<div class="sd-storyboard-model-picker">
        <label><span>生图渠道</span><select class="text_pole sd-storyboard-provider">${Object.values(STORYBOARD_PROVIDER_REGISTRY).filter(item => item.id !== 'comfy').map((item) => `<option value="${item.id}" ${state.source === item.id ? 'selected' : ''}>${htmlEscape(item.label)}</option>`).join('')}</select></label>
        <div class="sd-storyboard-model-field"><span>模型</span>${renderStoryboardModelPicker(state.source, profile.model, profile.capabilityModelId)}</div>
      </div>` : ''}
      ${profile.modelBindingError ? `<div class="sd-storyboard-connection-result failed" role="status"><span>${htmlEscape(profile.modelBindingError)}；请检查模型或连接。</span></div>` : ''}
      <div class="sd-storyboard-preset-field"><span>API 预设</span><div class="sd-storyboard-connection-preset-row"><select class="text_pole sd-storyboard-connection-preset"><option value="">选择生图 API 预设</option>${presetOptions}</select><button type="button" class="sd-icon-btn sd-storyboard-save-connection-preset" title="保存当前渠道的 API 预设" aria-label="保存当前渠道的 API 预设"><i class="fa-solid fa-bookmark"></i></button><button type="button" class="sd-icon-btn sd-danger sd-storyboard-delete-connection-preset" ${activePreset ? '' : 'disabled'} title="删除所选 API 预设" aria-label="删除所选 API 预设"><i class="fa-solid fa-trash-can"></i></button></div></div>
      <label><span>API 地址</span><input class="text_pole sd-storyboard-base-url" value="${htmlEscape(profile.baseUrl)}" placeholder="${htmlEscape(provider.defaultBaseUrl || 'http://127.0.0.1:8188')}"></label>
      <div class="sd-storyboard-key-field"><label for="sd-storyboard-key-input">${state.source === 'comfy' ? '访问令牌（可选）' : 'API Key'}</label><div class="sd-storyboard-key-control"><input id="sd-storyboard-key-input" class="text_pole sd-storyboard-api-key-memory" type="password" autocomplete="new-password" autocapitalize="off" spellcheck="false" value="${htmlEscape(storyboardDraftApiKeys.get(state.source) || '')}" placeholder="输入 API Key"><button type="button" class="sd-icon-btn sd-storyboard-key-visibility" title="显示 API Key" aria-label="显示 API Key" aria-pressed="false" aria-controls="sd-storyboard-key-input"><i class="fa-solid fa-eye" aria-hidden="true"></i></button></div></div>
      ${renderStoryboardConnectionCompatibility(state)}
      ${state.source === 'novel' ? `<label><span>执行方式</span><select class="text_pole sd-storyboard-service-mode" aria-label="执行方式"><option value="auto" ${connection.draft?.options?.imageTransport !== 'service' ? 'selected' : ''}>浏览器优先</option><option value="service" ${connection.draft?.options?.imageTransport === 'service' ? 'selected' : ''}>增强服务协调</option></select></label>` : ''}
      ${state.source === 'comfy' ? renderStoryboardComfyTransport(connection.draft) : ''}
      ${check ? `<div class="sd-storyboard-connection-result ${check.ok ? (check.verified === false ? 'partial' : 'ok') : 'failed'}"><i class="fa-solid ${check.ok && check.verified !== false ? 'fa-circle-check' : 'fa-triangle-exclamation'}"></i><span>${htmlEscape(check.message)}</span></div>` : ''}
      <div class="sd-storyboard-model-actions"><button type="button" class="sd-btn sd-storyboard-check-connection">测试连接</button><button type="button" class="sd-btn sd-primary sd-storyboard-save-connection">保存连接</button></div>
    </div>
  </details>`;
}

function renderStoryboardComfyTransport(connection) {
  const mode = getStoryboardComfyTransport(connection);
  return `<label><span>请求发出方</span><select class="text_pole sd-comfy-transport" aria-label="Comfy 请求发出方">
    <option value="gateway" ${mode === 'gateway' ? 'selected' : ''}>ST 主机 · 增强服务转发</option>
    <option value="browser" ${mode === 'browser' ? 'selected' : ''}>当前设备 · 浏览器直连</option>
    ${mode === 'legacy-auto' ? '<option value="legacy-auto" selected>旧连接 · 浏览器优先自动尝试</option>' : ''}
    ${mode === 'invalid' ? '<option value="invalid" selected disabled>请求方式待确认</option>' : ''}
  </select></label>
  <label class="sd-switch-row sd-comfy-private-network"><span>允许 ST 访问本地网络</span><input type="checkbox" class="sd-storyboard-private-network" ${connection?.options?.allowPrivateNetwork ? 'checked' : ''} ${mode === 'browser' ? 'disabled' : ''}></label>
  ${mode !== 'browser' ? '<details class="sd-comfy-targets"><summary>ST 可信连接</summary><div class="sd-comfy-targets-body"></div></details>' : ''}
  <details class="sd-comfy-deployment-guide"><summary>连接方式说明</summary><div>
    <p>本地 ST＋本地 Comfy：同机时可选 ST 转发，本机地址指 ST 电脑；手机打开 ST 时也不指手机。ST 私网连接须管理员登录并明确允许。</p>
    <p>本地 ST＋云 Comfy：填写云平台提供的 Comfy API 根地址和令牌；网页控制台地址不等于 API。浏览器直连还需服务允许浏览器访问。</p>
    <p>VPS ST＋云 Comfy：建议由 ST 主机转发，VPS 必须能够访问云端。容器内的本机地址不代表宿主机。</p>
    <p>测试、节点清单和生成沿用同一请求方式。${mode === 'legacy-auto' ? '旧连接仍会在浏览器传输失败时尝试 ST，建议明确选择发出方。' : '明确选择后失败不会改由另一台机器请求。'}ST 转发不提供内网穿透；只有私网地址时需平台安全入口或管理员配置互联，千幕不会自动开端口、关闭鉴权或安装隧道。</p>
  </div></details>`;
}

function renderStoryboardParameterVibes(state, profile, capabilities) {
  if (!capabilities.supportsVibe) return '';
  const selected = new Set(state.selectedVibeIds || []);
  const vibes = state.vibeLibrary.filter((item) => !item.providerIds?.length || item.providerIds.includes('novel'));
  const rows = vibes.slice(0, 24).map((item) => {
    const modelCompatible = !item.modelIds?.length || item.modelIds.includes(profile.capabilityModelId || profile.model);
    const disabled = !capabilities.vibe || !modelCompatible;
    return `<button type="button" class="sd-storyboard-param-vibe ${selected.has(item.id) ? 'active' : ''}" data-storyboard-param-vibe="${htmlEscape(item.id)}" ${disabled ? 'disabled' : ''} title="${disabled ? '当前 NovelAI 模型暂不支持这项 Vibe' : htmlEscape(item.name)}" aria-pressed="${selected.has(item.id)}">${storyboardSafeUrl(item.previewUrl) ? `<img src="${htmlEscape(storyboardSafeUrl(item.previewUrl))}" alt="">` : '<i class="fa-solid fa-image"></i>'}<span>${htmlEscape(item.name)}</span></button>`;
  }).join('');
  const status = capabilities.vibe ? (rows ? '选择后随本次绘制发送' : '尚未保存 Vibe') : '当前模型暂不支持';
  return `<div class="sd-storyboard-param-vibes ${capabilities.vibe ? '' : 'disabled'}"><div><span><b>Vibe</b><small>${status}</small></span><button type="button" class="sd-icon-btn sd-storyboard-open-vibe-library" title="打开 Vibe 库" aria-label="打开 Vibe 库"><i class="fa-solid fa-plus"></i></button></div>${rows ? `<div class="sd-storyboard-param-vibe-list">${rows}</div>` : ''}</div>`;
}

function storyboardGalleryRecords() {
  const store = getChatStore();
  if (!Array.isArray(store.storyboardImages)) store.storyboardImages = [];
  return store.storyboardImages;
}

function storyboardRecordChatKey(record, fallback = String(getChatKey() || '')) {
  return String(record?.chatKey || record?.messageRef?.chatKey || record?.snapshot?.chatKey || fallback || '');
}

function storyboardSnapshotKey(record, chatKey = storyboardRecordChatKey(record)) {
  const recordId = String(record?.id || '').trim();
  const owner = String(chatKey || '').trim();
  return recordId && owner ? `${owner}\u241f${recordId}` : '';
}

function storyboardSnapshotForRecord(record) {
  if (record?.recipeUnavailable) return null;
  if (record?.snapshot && typeof record.snapshot === 'object') return record.snapshot;
  const key = String(record?.snapshotRef || storyboardSnapshotKey(record));
  return key ? storyboardSnapshotCache.get(key) || null : null;
}

async function storyboardReadSnapshotForRecord(record) {
  if (record?.recipeUnavailable) return null;
  const immediate = storyboardSnapshotForRecord(record);
  if (immediate || !record || !blobStore.blobStoreAvailable()) return immediate;
  const expectedChatKey = storyboardRecordChatKey(record);
  const key = String(record.snapshotRef || storyboardSnapshotKey(record, expectedChatKey));
  if (!key || expectedChatKey !== String(getChatKey() || '')) return null;
  if (storyboardSnapshotReads.has(key)) return storyboardSnapshotReads.get(key);
  const epoch = storyboardSnapshotEpoch;
  const task = blobStore.getStoryboardSnapshots([key]).then((rows) => {
    if (epoch !== storyboardSnapshotEpoch || expectedChatKey !== String(getChatKey() || '')) return null;
    const snapshot = rows.find((item) => item?.key === key)?.snapshot || null;
    if (snapshot) {
      storyboardSnapshotCache.set(key, snapshot);
      record.snapshotRef = key;
      record.snapshotVersion = 1;
    }
    return snapshot;
  }).catch((error) => {
    console.warn('[千幕] 阅片重绘快照读取失败，继续使用画面轻量参数。', error);
    return null;
  }).finally(() => {
    if (storyboardSnapshotReads.get(key) === task) storyboardSnapshotReads.delete(key);
  });
  storyboardSnapshotReads.set(key, task);
  return task;
}

async function storyboardStoreSnapshotForRecord(record, snapshot) {
  if (!record || !snapshot || typeof snapshot !== 'object') return false;
  const expectedChatKey = storyboardRecordChatKey(record);
  const key = storyboardSnapshotKey(record, expectedChatKey);
  const safe = sanitizeStoryboardSnapshot(snapshot, { source: record.source, prompt: record.prompt, negative: record.negative });
  record.snapshot = safe;
  if (!key || !blobStore.blobStoreAvailable()) return false;
  const epoch = storyboardSnapshotEpoch;
  try {
    await blobStore.putStoryboardSnapshots([{ key, chatKey: expectedChatKey, recordId: record.id, snapshot: clone(safe) }]);
    if (epoch !== storyboardSnapshotEpoch || expectedChatKey !== String(getChatKey() || '') || record.snapshot !== safe) return false;
    storyboardSnapshotCache.set(key, clone(safe));
    record.chatKey = expectedChatKey;
    record.snapshotRef = key;
    record.snapshotVersion = 1;
    delete record.snapshot;
    return true;
  } catch (error) {
    console.warn('[千幕] 阅片重绘快照暂未归档，已保留聊天内原数据。', error);
    return false;
  }
}

async function storyboardArchiveGallerySnapshots(records = storyboardGalleryRecords()) {
  const expectedChatKey = String(getChatKey() || '');
  const epoch = storyboardSnapshotEpoch;
  const captures = (Array.isArray(records) ? records : []).filter((record) => (
    record?.id && record.snapshot && typeof record.snapshot === 'object'
      && storyboardRecordChatKey(record, expectedChatKey) === expectedChatKey
  )).map((record) => ({
    record,
    source: record.snapshot,
    key: storyboardSnapshotKey(record, expectedChatKey),
    snapshot: sanitizeStoryboardSnapshot(record.snapshot, { source: record.source, prompt: record.prompt, negative: record.negative }),
  })).filter((item) => item.key);
  if (!captures.length || !blobStore.blobStoreAvailable()) return 0;
  try {
    await blobStore.putStoryboardSnapshots(captures.map((item) => ({
      key: item.key, chatKey: expectedChatKey, recordId: item.record.id, snapshot: clone(item.snapshot),
    })));
    if (epoch !== storyboardSnapshotEpoch || expectedChatKey !== String(getChatKey() || '')) return 0;
    const stripped = [];
    const currentById = new Map(storyboardGalleryRecords().map((record) => [String(record?.id || ''), record]));
    const abandonedKeys = [];
    for (const item of captures) {
      const current = currentById.get(String(item.record.id || ''));
      if (current !== item.record) {
        if (!current) abandonedKeys.push(item.key);
        continue;
      }
      if (item.record.snapshot !== item.source) continue;
      storyboardSnapshotCache.set(item.key, clone(item.snapshot));
      item.record.chatKey = expectedChatKey;
      item.record.snapshotRef = item.key;
      item.record.snapshotVersion = 1;
      delete item.record.snapshot;
      stripped.push(item);
    }
    if (abandonedKeys.length) void blobStore.deleteStoryboardSnapshots(abandonedKeys).catch(() => {});
    if (!stripped.length) return 0;
    try { await saveMetadata(); }
    catch (error) {
      for (const item of stripped) item.record.snapshot = item.source;
      throw error;
    }
    return stripped.length;
  } catch (error) {
    console.warn('[千幕] 阅片快照渐进迁移未完成，旧聊天数据保持原样。', error);
    return 0;
  }
}

async function storyboardHydrateGallerySnapshots(records = storyboardGalleryRecords(), { migrate = true } = {}) {
  if (migrate) await storyboardArchiveGallerySnapshots(records);
  const expectedChatKey = String(getChatKey() || '');
  const epoch = storyboardSnapshotEpoch;
  const missing = (Array.isArray(records) ? records : []).map((record) => ({
    record, key: String(record?.snapshotRef || storyboardSnapshotKey(record, expectedChatKey)),
  })).filter((item) => item.record && !item.record.snapshot && item.key && !storyboardSnapshotCache.has(item.key));
  if (!missing.length || !blobStore.blobStoreAvailable()) return 0;
  try {
    const rows = await blobStore.getStoryboardSnapshots(missing.map((item) => item.key));
    if (epoch !== storyboardSnapshotEpoch || expectedChatKey !== String(getChatKey() || '')) return 0;
    for (const row of rows) if (row?.key && row.snapshot) storyboardSnapshotCache.set(String(row.key), row.snapshot);
    return rows.length;
  } catch (error) {
    console.warn('[千幕] 阅片重绘快照批量读取失败，图片浏览仍可继续。', error);
    return 0;
  }
}

async function storyboardDeleteRecordSnapshots(records) {
  const list = (Array.isArray(records) ? records : [records]).filter(Boolean);
  const keys = [...new Set(list.map((record) => String(record.snapshotRef || storyboardSnapshotKey(record))).filter(Boolean))];
  for (const key of keys) storyboardSnapshotCache.delete(key);
  if (!keys.length || !blobStore.blobStoreAvailable()) return 0;
  try {
    await blobStore.deleteStoryboardSnapshots(keys);
    return keys.length;
  } catch (error) {
    console.warn('[千幕] 已删除画面记录，但残留重绘快照需由储存空间继续清理。', error);
    return 0;
  }
}

function storyboardPlanIsTerminal(plan) {
  return Boolean(plan?.id) && ['completed', 'skipped', 'failed', 'cancelled', 'stale', 'orphaned'].includes(String(plan.status || ''));
}

function storyboardPlanArchiveKey(plan) {
  const planId = String(plan?.id || '').trim();
  const chatKey = String(plan?.chatKey || plan?.messageRef?.chatKey || 'unscoped').trim() || 'unscoped';
  return planId ? `${chatKey}\u241f${planId}` : '';
}

function storyboardPlanHasHeavyPayload(plan) {
  if (!plan || !storyboardPlanIsTerminal(plan)) return false;
  if (plan.continuityLedger && typeof plan.continuityLedger === 'object') return true;
  return (plan.shots || []).some((shot) => (
    String(shot?.prompt || '').trim() || String(shot?.safePrompt || '').trim() || String(shot?.negative || '').trim()
      || shot?.shotSpec || shot?.compiledPrompt || shot?.compositionDecision
  ));
}

function storyboardPlanArchivePayload(plan) {
  const payload = clone(plan);
  delete payload.archiveRef;
  delete payload.archiveVersion;
  delete payload.archivedAt;
  return payload;
}

function storyboardPlanLightweightSummary(plan, key) {
  return {
    id: plan.id, chatKey: plan.chatKey, floor: plan.floor, swipeId: plan.swipeId,
    messageRef: clone(plan.messageRef || null), revisionId: plan.revisionId, idempotencyKey: plan.idempotencyKey,
    origin: plan.origin, paragraphSelection: clone(plan.paragraphSelection || null),
    continuityLedger: null, hasContinuityLedger: Boolean(plan.hasContinuityLedger || plan.continuityLedger),
    autoGenerate: Boolean(plan.autoGenerate), promptLocked: Boolean(plan.promptLocked), manualReviewRequired: Boolean(plan.manualReviewRequired),
    status: plan.status, linkState: plan.linkState || '',
    shots: (plan.shots || []).map((shot) => ({
      id: shot.id, shotType: shot.shotType, role: shot.role, title: shot.title, purpose: '',
      prompt: '', safePrompt: '', negative: '', hasPrompt: Boolean(shot.hasPrompt || String(shot.prompt || '').trim() || String(shot.safePrompt || '').trim()),
      providerId: shot.providerId, connectionPresetId: shot.connectionPresetId, parameterPresetId: shot.parameterPresetId, routeRuleId: shot.routeRuleId,
      status: shot.status, resultIds: clone(shot.resultIds || []), error: String(shot.error || '').slice(0, 400),
      partialFailureCount: shot.partialFailureCount, attempt: shot.attempt,
      paragraphAnchor: clone(shot.paragraphAnchor || null), paragraphSelection: clone(shot.paragraphSelection || null),
      shotSpec: null, compiledPrompt: null, compositionDecision: null,
      sensitive: Boolean(shot.sensitive), safetyAdapted: Boolean(shot.safetyAdapted), safetyMethod: String(shot.safetyMethod || '').slice(0, 40), userEdited: Boolean(shot.userEdited),
      promptLocked: Boolean(shot.promptLocked), requiresManualConfirmation: Boolean(shot.requiresManualConfirmation),
    })),
    archiveRef: key, archiveVersion: 1, archivedAt: Date.now(), createdAt: plan.createdAt, updatedAt: plan.updatedAt,
  };
}

async function storyboardArchiveShotPlans(plans = storyboardState().shotPlans) {
  if (!blobStore.blobStoreAvailable()) return 0;
  const candidates = (Array.isArray(plans) ? plans : []).filter((plan) => storyboardPlanHasHeavyPayload(plan));
  if (!candidates.length) return 0;
  const epoch = storyboardPlanArchiveEpoch;
  const captures = candidates.map((plan) => ({
    id: String(plan.id), key: storyboardPlanArchiveKey(plan), chatKey: String(plan.chatKey || plan.messageRef?.chatKey || ''),
    updatedAt: Number(plan.updatedAt) || 0, status: String(plan.status || ''), plan: storyboardPlanArchivePayload(plan),
  })).filter((item) => item.key);
  if (!captures.length) return 0;
  try {
    await blobStore.putStoryboardPlanArchives(captures.map((item) => ({
      key: item.key, chatKey: item.chatKey, planId: item.id, plan: clone(item.plan), updatedAt: item.updatedAt,
    })));
    if (epoch !== storyboardPlanArchiveEpoch) return 0;
    const state = storyboardState();
    let archived = 0;
    for (const item of captures) {
      const index = state.shotPlans.findIndex((plan) => String(plan.id) === item.id);
      const current = index >= 0 ? state.shotPlans[index] : null;
      if (!current || Number(current.updatedAt || 0) !== item.updatedAt || String(current.status || '') !== item.status || !storyboardPlanIsTerminal(current)) continue;
      storyboardPlanArchiveCache.set(item.key, clone(item.plan));
      state.shotPlans[index] = storyboardPlanLightweightSummary(current, item.key);
      archived++;
    }
    if (archived) saveSettings();
    return archived;
  } catch (error) {
    console.warn('[千幕] 分镜历史计划暂未归档，已保留设置内原数据。', error);
    return 0;
  }
}

function storyboardSchedulePlanArchive(delay = 180) {
  if (storyboardPlanArchiveTimer) clearTimeout(storyboardPlanArchiveTimer);
  storyboardPlanArchiveTimer = setTimeout(() => {
    storyboardPlanArchiveTimer = null;
    void storyboardArchiveShotPlans();
  }, Math.max(0, Number(delay) || 0));
}

async function storyboardReleasePlanArchive(plan) {
  if (!plan) return;
  const key = String(plan.archiveRef || storyboardPlanArchiveKey(plan));
  delete plan.archiveRef;
  delete plan.archiveVersion;
  delete plan.archivedAt;
  plan.continuityLedger ||= null;
  if (!key) return;
  storyboardPlanArchiveCache.delete(key);
  if (!blobStore.blobStoreAvailable()) return;
  try { await blobStore.deleteStoryboardPlanArchives([key]); }
  catch (error) { console.warn('[千幕] 分镜历史计划恢复为工作态时，旧归档稍后可由储存空间清理。', error); }
}

async function storyboardPlansForPortableExport(plans = []) {
  const list = Array.isArray(plans) ? plans : [];
  const keys = [...new Set(list.map((plan) => String(plan?.archiveRef || '')).filter(Boolean))];
  const missing = keys.filter((key) => !storyboardPlanArchiveCache.has(key));
  if (missing.length && blobStore.blobStoreAvailable()) {
    try {
      const rows = await blobStore.getStoryboardPlanArchives(missing);
      for (const row of rows) if (row?.key && row.plan) storyboardPlanArchiveCache.set(String(row.key), row.plan);
    } catch (error) {
      console.warn('[千幕] 分镜历史计划读取失败，将导出仍可用的轻量索引。', error);
    }
  }
  return list.map((summary) => {
    const archived = summary?.archiveRef ? storyboardPlanArchiveCache.get(String(summary.archiveRef)) : null;
    const output = archived ? clone(archived) : clone(summary);
    if (archived) {
      Object.assign(output, {
        id: summary.id, chatKey: summary.chatKey, floor: summary.floor, swipeId: summary.swipeId,
        messageRef: clone(summary.messageRef || null), revisionId: summary.revisionId, idempotencyKey: summary.idempotencyKey,
        origin: summary.origin, paragraphSelection: clone(summary.paragraphSelection || null), autoGenerate: summary.autoGenerate,
        promptLocked: summary.promptLocked, manualReviewRequired: summary.manualReviewRequired,
        status: summary.status, linkState: summary.linkState || '', createdAt: summary.createdAt, updatedAt: summary.updatedAt,
      });
      const currentShots = new Map((summary.shots || []).map((shot) => [String(shot.id || ''), shot]));
      output.shots = (archived.shots || []).map((shot) => {
        const current = currentShots.get(String(shot.id || ''));
        return current ? { ...shot, status: current.status, resultIds: clone(current.resultIds || []), error: current.error, attempt: current.attempt, partialFailureCount: current.partialFailureCount } : shot;
      });
    }
    delete output.archiveRef;
    delete output.archiveVersion;
    delete output.archivedAt;
    return output;
  });
}

async function storyboardDeletePlanArchives(plans) {
  const list = (Array.isArray(plans) ? plans : [plans]).filter(Boolean);
  const keys = [...new Set(list.map((plan) => String(plan.archiveRef || storyboardPlanArchiveKey(plan))).filter(Boolean))];
  for (const key of keys) storyboardPlanArchiveCache.delete(key);
  if (!keys.length || !blobStore.blobStoreAvailable()) return 0;
  try {
    await blobStore.deleteStoryboardPlanArchives(keys);
    return keys.length;
  } catch (error) {
    console.warn('[千幕] 过期分镜计划索引已移除，残留归档可在储存空间继续清理。', error);
    return 0;
  }
}

function storyboardGalleryCollections() {
  const store = getChatStore();
  if (!Array.isArray(store.storyboardCollections)) store.storyboardCollections = [];
  store.storyboardCollections = store.storyboardCollections
    .filter((item) => item && String(item.id || '').trim() && String(item.name || '').trim())
    .slice(0, 120);
  return store.storyboardCollections;
}

async function storyboardStoreDeferredDelivery(job, records) {
  const delivery = {
    taskId: job.id, chatKey: String(job.chatKey || ''), target: job.target || 'gallery',
    planId: job.planId || '', shotId: job.planShotId || '', records: clone(records || []), createdAt: Date.now(),
  };
  try {
    await blobStore.putStoryboardDelivery(job.id, delivery);
    storyboardVolatileDeliveries.delete(job.id);
    return 'pending_chat';
  } catch (error) {
    storyboardVolatileDeliveries.set(job.id, delivery);
    console.warn(`[${MODULE_NAME}] storyboard delivery inbox unavailable; keeping this result for the current page`, error);
    return 'volatile_pending';
  }
}

async function storyboardDrainPendingDeliveries(chatKey = String(getChatKey() || '')) {
  const expectedChatKey = String(chatKey || '');
  if (!expectedChatKey) return 0;
  const previousDrain = storyboardDeliveryDrainPromise;
  const runDrain = async () => {
    let durable = [];
    try { durable = await blobStore.listStoryboardDeliveries(expectedChatKey); }
    catch (error) { console.warn(`[${MODULE_NAME}] storyboard delivery inbox read failed`, error); }
    const deliveries = new Map();
    for (const item of durable) if (item?.taskId) deliveries.set(String(item.taskId), item);
    for (const item of storyboardVolatileDeliveries.values()) {
      if (item?.chatKey === expectedChatKey && item.taskId) deliveries.set(String(item.taskId), item);
    }
    if (!deliveries.size || String(getChatKey() || '') !== expectedChatKey) return 0;
    const chat = Array.isArray(ctx().chat) ? ctx().chat : [];
    const gallery = storyboardGalleryRecords();
    const knownIds = new Set(gallery.map((item) => String(item.id || '')));
    const galleryById = new Map(gallery.map((item) => [String(item.id || ''), item]));
    const state = storyboardState();
    const changedTasks = new Map();
    const touchedFloors = new Set();
    const receivedRecords = [];
    let received = 0;
    for (const delivery of deliveries.values()) {
      let deliveryLinkState = '';
      const deliveryFloors = new Set();
      const resultIds = [];
      for (const raw of Array.isArray(delivery.records) ? delivery.records : []) {
        if (!raw?.id) continue;
        if (knownIds.has(String(raw.id))) {
          const existing = galleryById.get(String(raw.id));
          resultIds.push(String(raw.id));
          if (Number.isInteger(existing?.floor)) deliveryFloors.add(existing.floor);
          deliveryLinkState ||= existing?.linkState || '';
          continue;
        }
        const record = clone(raw);
        const resolved = record.messageRef?.messageKey
          ? resolveStoryboardMessageReference(record.messageRef, chat, { chatKey: expectedChatKey })
          : null;
        if (resolved?.state === 'active') {
          record.floor = resolved.floor;
          record.inline = record.requestedInline !== false;
          record.messageHash = hashText(String(resolved.message?.mes || ''));
          record.swipeId = Number(resolved.message?.swipe_id || 0);
          record.linkState = 'active';
          touchedFloors.add(resolved.floor);
          deliveryFloors.add(resolved.floor);
          deliveryLinkState = 'active';
        } else {
          record.lastKnownFloor = Number.isInteger(record.lastKnownFloor) ? record.lastKnownFloor : (Number.isInteger(record.floor) ? record.floor : null);
          record.floor = null;
          record.inline = false;
          record.linkState = resolved?.state || (delivery.target === 'gallery' ? '' : 'orphaned');
          deliveryLinkState ||= record.linkState;
        }
        gallery.push(record);
        receivedRecords.push(record);
        knownIds.add(String(record.id));
        galleryById.set(String(record.id), record);
        resultIds.push(String(record.id));
        received++;
      }
      const task = (state.taskStates || []).find((item) => item.id === delivery.taskId);
      if (task) changedTasks.set(task.id, transitionStoryboardTaskState(task, 'completed', {
        stage: 'complete', progress: 1, resultIds: resultIds.length ? resultIds : task.resultIds,
        floor: deliveryFloors.size ? [...deliveryFloors].at(-1) : null,
        deliveryState: deliveryFloors.size || delivery.target === 'gallery' ? 'delivered' : 'gallery_fallback',
        linkState: deliveryLinkState,
      }));
    }
    if (!received) {
      if (changedTasks.size) {
        state.taskStates = state.taskStates.map((task) => changedTasks.get(task.id) || task);
        saveSettings();
      }
      for (const delivery of deliveries.values()) {
        storyboardVolatileDeliveries.delete(delivery.taskId);
        try { await blobStore.deleteStoryboardDelivery(delivery.taskId); } catch (_) {}
      }
      return 0;
    }
    const prunedRecords = gallery.length > 400 ? gallery.splice(0, gallery.length - 400) : [];
    await saveMetadata();
    void storyboardArchiveGallerySnapshots(receivedRecords);
    if (prunedRecords.length) void storyboardDeleteRecordSnapshots(prunedRecords);
    if (String(getChatKey() || '') !== expectedChatKey) return 0;
    if (changedTasks.size) state.taskStates = state.taskStates.map((task) => changedTasks.get(task.id) || task);
    saveSettings();
    for (const delivery of deliveries.values()) {
      storyboardVolatileDeliveries.delete(delivery.taskId);
      try { await blobStore.deleteStoryboardDelivery(delivery.taskId); }
      catch (error) { console.warn(`[${MODULE_NAME}] storyboard delivery inbox cleanup failed`, error); }
    }
    if (touchedFloors.size) touchedFloors.forEach((floor) => storyboardScheduleInlineRender(40, floor));
    else storyboardScheduleInlineRender(40);
    rerenderIfOpen();
    toast(`已接收 ${received} 张跨聊天完成的分镜。`, 'success');
    return received;
  };
  const scheduledDrain = (previousDrain ? previousDrain.catch(() => 0) : Promise.resolve()).then(runDrain);
  storyboardDeliveryDrainPromise = scheduledDrain;
  try { return await scheduledDrain; }
  finally { if (storyboardDeliveryDrainPromise === scheduledDrain) storyboardDeliveryDrainPromise = null; }
}

function storyboardItemCollectionIds(item) {
  return uniqueClean([...(Array.isArray(item?.collectionIds) ? item.collectionIds : []), item?.collectionId])
    .map((id) => String(id || '').trim()).filter(Boolean).slice(0, 30);
}

function storyboardAssignCollectionIds(item, values) {
  const ids = uniqueClean(values).map((id) => String(id || '').trim()).filter(Boolean).slice(0, 30);
  item.collectionIds = ids;
  item.collectionId = ids[0] || '';
  return ids;
}

function storyboardMediaTagChipMarkup(tag) {
  const value = String(tag || '').trim().slice(0, 80);
  if (!value) return '';
  return `<span class="sd-media-tag-chip" data-media-tag="${htmlEscape(value)}"><button type="button" class="sd-media-tag-rename" title="编辑标签">${htmlEscape(value)}</button><button type="button" class="sd-media-tag-remove" title="删除标签" aria-label="删除标签 ${htmlEscape(value)}"><i class="fa-solid fa-xmark"></i></button></span>`;
}

function storyboardMediaTagEditorMarkup(tags, knownTags, scope) {
  const selected = uniqueClean(tags || []).slice(0, 30);
  const suggestions = uniqueClean(knownTags || []).filter((tag) => !selected.includes(tag)).slice(0, 40);
  return `<div class="sd-media-tag-editor" data-media-tag-editor="${htmlEscape(scope)}"><div class="sd-media-tag-chips">${selected.map(storyboardMediaTagChipMarkup).join('')}</div><div class="sd-media-tag-input-row"><input class="text_pole sd-media-tag-input" maxlength="80" placeholder="添加标签"><div class="sd-media-tag-suggestions">${suggestions.map((tag) => `<button type="button" data-media-tag-suggestion="${htmlEscape(tag)}">${htmlEscape(tag)}</button>`).join('')}</div></div></div>`;
}

function storyboardMediaSidebarMarkup({ allCount, collections, currentId, countFor, tags, scope }) {
  const collectionRows = collections.map((collection) => `<div class="sd-media-collection-row ${currentId === collection.id ? 'active' : ''}" data-${scope}-collection="${htmlEscape(collection.id)}"><button type="button" class="sd-media-collection-open"><i class="fa-regular fa-folder"></i><span>${htmlEscape(collection.name)}</span><em>${countFor(collection.id)}</em></button><div><button type="button" class="sd-icon-btn sd-media-collection-rename" title="重命名" aria-label="重命名"><i class="fa-solid fa-pen"></i></button><button type="button" class="sd-icon-btn sd-danger sd-media-collection-delete" title="解散合集" aria-label="解散合集"><i class="fa-solid fa-xmark"></i></button></div></div>`).join('');
  return `<aside class="sd-media-sidebar"><div class="sd-media-sidebar-section"><b>资料库</b><button type="button" class="sd-media-all ${currentId ? '' : 'active'}"><i class="fa-regular fa-images"></i><span>全部</span><em>${allCount}</em></button></div><div class="sd-media-sidebar-section"><b>合集</b><div class="sd-media-collection-list">${collectionRows || '<small>暂无合集</small>'}</div></div>${tags.length ? `<div class="sd-media-sidebar-section sd-media-sidebar-tags"><b>标签</b><div>${tags.slice(0, 18).map((tag) => `<button type="button" data-${scope}-tag-filter="${htmlEscape(tag)}">${htmlEscape(tag)}</button>`).join('')}</div></div>` : ''}</aside>`;
}

function storyboardMediaTagValues(editor) {
  return uniqueClean(Array.from(editor?.querySelectorAll?.('[data-media-tag]') || []).map((chip) => String(chip.dataset.mediaTag || '').trim())).slice(0, 30);
}

function storyboardPersistMediaTagEditor(editor) {
  const scope = String(editor?.dataset.mediaTagEditor || '');
  if (!scope.startsWith('gallery:')) return;
  const record = storyboardGalleryRecords().find((item) => item.id === scope.slice(8));
  if (!record) return;
  record.tags = storyboardMediaTagValues(editor);
  void saveMetadata();
}

function storyboardMediaTagAdd(editor, rawValue) {
  const value = String(rawValue || '').trim().replace(/^#+/, '').slice(0, 80);
  if (!value) return false;
  const values = storyboardMediaTagValues(editor);
  if (values.some((tag) => tag.toLocaleLowerCase() === value.toLocaleLowerCase()) || values.length >= 30) return false;
  editor.querySelector('.sd-media-tag-chips')?.insertAdjacentHTML('beforeend', storyboardMediaTagChipMarkup(value));
  editor.querySelector(`[data-media-tag-suggestion="${CSS.escape(value)}"]`)?.setAttribute('hidden', '');
  applyQianmuIcons(editor);
  storyboardPersistMediaTagEditor(editor);
  return true;
}

function storyboardMediaTagFilterSuggestions(editor, query) {
  const value = String(query || '').trim().toLocaleLowerCase();
  editor.querySelectorAll('[data-media-tag-suggestion]').forEach((button) => {
    const selected = storyboardMediaTagValues(editor).some((tag) => tag.toLocaleLowerCase() === String(button.dataset.mediaTagSuggestion || '').toLocaleLowerCase());
    button.hidden = selected || Boolean(value && !String(button.dataset.mediaTagSuggestion || '').toLocaleLowerCase().includes(value));
  });
}

function storyboardBindMediaTagEditors(root) {
  root.querySelectorAll('[data-media-tag-editor]').forEach((editor) => {
    const input = editor.querySelector('.sd-media-tag-input');
    const commit = (value) => {
      String(value || '').split(/[,，\n]+/).forEach((tag) => storyboardMediaTagAdd(editor, tag));
      if (input) { input.value = ''; storyboardMediaTagFilterSuggestions(editor, ''); input.focus(); }
    };
    input?.addEventListener('keydown', (event) => {
      if (event.key !== 'Enter' && event.key !== ',') return;
      event.preventDefault(); commit(input.value);
    });
    input?.addEventListener('input', () => {
      if (/[,，\n]/.test(input.value)) {
        const parts = input.value.split(/[,，\n]+/);
        const tail = parts.pop() || '';
        parts.forEach((tag) => storyboardMediaTagAdd(editor, tag));
        input.value = tail;
      }
      storyboardMediaTagFilterSuggestions(editor, input.value);
    });
    editor.querySelectorAll('[data-media-tag-suggestion]').forEach((button) => button.addEventListener('click', () => commit(button.dataset.mediaTagSuggestion)));
    editor.addEventListener('click', async (event) => {
      const remove = event.target.closest('.sd-media-tag-remove');
      if (remove) {
        remove.closest('[data-media-tag]')?.remove();
        storyboardPersistMediaTagEditor(editor);
        storyboardMediaTagFilterSuggestions(editor, input?.value || '');
        return;
      }
      const rename = event.target.closest('.sd-media-tag-rename');
      if (!rename) return;
      const chip = rename.closest('[data-media-tag]');
      const oldValue = String(chip?.dataset.mediaTag || '');
      const answer = await promptInput('编辑标签', '输入新的标签名。', oldValue);
      const value = String(answer ?? '').trim().replace(/^#+/, '').slice(0, 80);
      if (!chip || !value || value === oldValue) return;
      if (storyboardMediaTagValues(editor).some((tag) => tag !== oldValue && tag.toLocaleLowerCase() === value.toLocaleLowerCase())) return toast('已有同名标签。', 'warning');
      chip.dataset.mediaTag = value;
      rename.textContent = value;
      chip.querySelector('.sd-media-tag-remove')?.setAttribute('aria-label', `删除标签 ${value}`);
      storyboardPersistMediaTagEditor(editor);
      storyboardMediaTagFilterSuggestions(editor, input?.value || '');
    });
  });
}

function storyboardGalleryGroupId(record) {
  return String(record?.variantRootId || record?.planShotId || record?.groupId || record?.id || '');
}

function storyboardGalleryGroups(records) {
  const groups = new Map();
  for (const record of records) {
    const id = storyboardGalleryGroupId(record);
    if (!id) continue;
    if (!groups.has(id)) groups.set(id, []);
    groups.get(id).push(record);
  }
  return [...groups.entries()].map(([id, variants]) => ({
    id,
    variants: variants.sort((a, b) => Number(b.createdAt || 0) - Number(a.createdAt || 0)),
  })).sort((a, b) => Number(b.variants[0]?.createdAt || 0) - Number(a.variants[0]?.createdAt || 0));
}

function storyboardPlanCompilerSignature(state = storyboardState()) {
  return hashText([
    state.promptCompiler?.apiProfileId || 'current-api',
    state.promptCompiler?.instructionPresetId || 'default',
    JSON.stringify(storyboardCompilerTagRules(state)),
    Number(state.promptCompiler?.includeRecentFloors) || 0,
    state.promptCompiler?.includeCharacterCards !== false,
    state.promptCompiler?.includeUserPersona !== false,
    state.promptCompiler?.worldMode || 'auto',
    (state.promptCompiler?.worldEntryIds || []).join(','),
    state.paragraphMode || 'auto',
  ].join('\u241f'));
}

function storyboardPlanForMessage(state, floor, message) {
  if (!message || !Number.isInteger(floor)) return null;
  const chatKey = String(getChatKey() || '');
  const reference = createStoryboardMessageReference({ message, chatKey, floor });
  return (state.shotPlans || []).find((plan) => plan.chatKey === chatKey
    && plan.messageRef?.messageKey === reference.messageKey
    && plan.revisionId === reference.revisionId
    && plan.origin !== 'manual_supplement') || null;
}

function storyboardEnsurePlan(state, floor, message, { origin = 'manual', autoGenerate = false, forceNew = false, paragraphSelection = null } = {}) {
  let plan = forceNew ? null : storyboardPlanForMessage(state, floor, message);
  if (plan) return plan;
  const chatKey = String(getChatKey() || '');
  const messageRef = createStoryboardMessageReference({ message, chatKey, floor });
  const ticket = createStoryboardWorkflowTicket({
    id: forceNew ? uid('story') : '', messageRef, chatKey, floor, origin, autoGenerate, paragraphSelection,
    compilerSignature: storyboardPlanCompilerSignature(state), createdAt: Date.now(),
  });
  plan = { ...ticket, shots: [], status: 'idle' };
  const next = [plan, ...(state.shotPlans || []).filter((item) => item.id !== plan.id)];
  const dropped = next.slice(300);
  state.shotPlans = next.slice(0, 300);
  if (dropped.length) void storyboardDeletePlanArchives(dropped);
  return plan;
}

function storyboardPlanForJob(job) {
  if (!job?.planId) return null;
  return storyboardState().shotPlans.find((plan) => plan.id === job.planId) || null;
}

function storyboardSyncTaskState(job, status, { error = '', resultIds = null, floor = undefined, stage = '', progress = null, plan = null, deliveryState = '', linkState = '' } = {}) {
  if (!job?.id) return null;
  const state = storyboardState();
  const current = (state.taskStates || []).find((item) => item.id === job.id);
  const targetFloor = floor === null ? null : (Number.isInteger(floor) ? floor : (Number.isInteger(job.floor) ? job.floor : null));
  const base = current || createStoryboardTaskState({
    id: job.id, planId: job.planId, shotId: job.planShotId, logId: job.logId,
    chatKey: job.chatKey, floor: targetFloor, messageRef: job.messageRef,
    paragraphAnchor: job.paragraphAnchor, paragraphSelection: job.paragraphSelection,
    uiVisible: plan?.origin === 'manual_supplement', status: 'queued',
  });
  const next = transitionStoryboardTaskState(base, status, {
    planId: job.planId, shotId: job.planShotId, logId: job.logId,
    chatKey: job.chatKey, floor: targetFloor, messageRef: job.messageRef,
    paragraphAnchor: job.paragraphAnchor, paragraphSelection: job.paragraphSelection,
    uiVisible: current?.uiVisible ?? plan?.origin === 'manual_supplement',
    ...(stage ? { stage } : {}), ...(progress == null ? {} : { progress }),
    ...(deliveryState ? { deliveryState } : {}), ...(linkState ? { linkState } : {}),
    ...(error ? { error: String(error).slice(0, 4000) } : {}),
    ...(Array.isArray(resultIds) ? { resultIds } : {}),
  });
  state.taskStates = [next, ...(state.taskStates || []).filter((item) => item.id !== next.id)].slice(0, 300);
  return next;
}

function storyboardSetPlanStatus(plan, status, { error = '', resultIds = null, job = null, floor = undefined, stage = '', progress = null, deliveryState = '', linkState = '' } = {}) {
  const task = storyboardSyncTaskState(job, status, { error, resultIds, floor, stage, progress, plan, deliveryState, linkState });
  if (plan) {
    const shot = job?.planShotId ? plan.shots?.find((item) => item.id === job.planShotId) : null;
    if (shot) {
      const siblingTasks = (storyboardState().taskStates || []).filter((item) => item.planId === plan.id && item.shotId === shot.id);
      const aggregate = aggregateStoryboardShotTasks(siblingTasks, status);
      shot.status = aggregate.status;
      shot.error = aggregate.error;
      shot.partialFailureCount = aggregate.partialFailureCount;
      shot.attempt = Math.max(Number(shot.attempt) || 0, Number(job?.attempt) || 0);
      shot.resultIds = [...new Set([...(shot.resultIds || []), ...aggregate.resultIds].map(String))].slice(-20);
    }
    const shotStates = (plan.shots || []).map((item) => item.status);
    if (!shot || !shotStates.length) plan.status = status;
    else if (shotStates.includes('generating')) plan.status = 'generating';
    else if (shotStates.includes('queued')) plan.status = 'queued';
    else if (shotStates.includes('compiling')) plan.status = 'compiling';
    else if (shotStates.includes('prompt_ready')) plan.status = 'prompt_ready';
    else if (shotStates.every((item) => item === 'completed')) plan.status = 'completed';
    else if (shotStates.some((item) => item === 'completed')) plan.status = 'completed';
    else if (shotStates.every((item) => ['failed', 'cancelled', 'orphaned', 'stale'].includes(item))) plan.status = status;
    else plan.status = status;
    plan.updatedAt = Date.now();
    if (error && !shot) plan.error = String(error).slice(0, 4000);
  }
  if (!plan && !task) return;
  saveSettings();
  if (storyboardPlanIsTerminal(plan)) storyboardSchedulePlanArchive();
  const renderFloor = Number.isInteger(task?.floor) ? task.floor : (Number.isInteger(plan?.floor) ? plan.floor : null);
  const currentOwnsTask = !job?.chatKey || job.chatKey === String(getChatKey() || '');
  if (currentOwnsTask && Number.isInteger(renderFloor)) storyboardScheduleInlineRender(30, renderFloor);
}

function storyboardReconcileShotPlans() {
  const state = storyboardState();
  const chat = Array.isArray(ctx().chat) ? ctx().chat : [];
  const chatKey = String(getChatKey() || '');
  let changed = false;
  for (const plan of state.shotPlans || []) {
    if (!plan?.messageRef?.messageKey || plan.chatKey !== chatKey) continue;
    const resolved = resolveStoryboardMessageReference(plan.messageRef, chat, { chatKey });
    const previousFloor = plan.floor;
    const previousState = plan.linkState || '';
    if (['active', 'stale', 'inactive_swipe'].includes(resolved.state)) {
      plan.floor = resolved.floor;
      plan.messageRef.lastKnownFloor = resolved.floor;
      if (resolved.state === 'inactive_swipe') plan.linkState = 'inactive_swipe';
      else plan.linkState = resolved.state;
    } else if (resolved.state === 'orphaned') {
      plan.floor = null;
      plan.linkState = 'orphaned';
      if (!['completed', 'failed', 'cancelled'].includes(plan.status)) plan.status = 'orphaned';
    }
    if (previousFloor !== plan.floor || previousState !== plan.linkState) changed = true;
  }
  if (changed) {
    queueMicrotask(() => saveSettings());
    storyboardSchedulePlanArchive();
  }
  return changed;
}

function storyboardScheduleLinkSave() {
  if (storyboardLinkSaveQueued) return;
  storyboardLinkSaveQueued = true;
  queueMicrotask(async () => {
    storyboardLinkSaveQueued = false;
    try { await saveMetadata(); }
    catch (error) { console.warn(`[${MODULE_NAME}] storyboard message-link save failed`, error); }
  });
}

function storyboardRecoverLegacyMessageReference(record, chat, chatKey) {
  const expectedHash = String(record?.messageHash || '');
  const expectedSwipe = Number(record?.swipeId || 0);
  const directFloor = Number.isInteger(record?.floor) ? record.floor : null;
  const direct = Number.isInteger(directFloor) ? chat[directFloor] : null;
  if (direct && (!expectedHash || expectedHash === hashText(String(direct.mes || ''))) && expectedSwipe === Number(direct.swipe_id || 0)) {
    return createStoryboardMessageReference({ message: direct, chatKey, floor: directFloor });
  }
  if (!expectedHash) return null;
  const candidates = [];
  chat.forEach((message, floor) => {
    if (!message || expectedHash !== hashText(String(message.mes || '')) || expectedSwipe !== Number(message.swipe_id || 0)) return;
    candidates.push({ message, floor });
  });
  if (!candidates.length) return null;
  candidates.sort((a, b) => Math.abs(a.floor - Number(directFloor || 0)) - Math.abs(b.floor - Number(directFloor || 0)));
  return createStoryboardMessageReference({ message: candidates[0].message, chatKey, floor: candidates[0].floor });
}

function storyboardReconcileGalleryLinks({ persist = true } = {}) {
  const chat = Array.isArray(ctx().chat) ? ctx().chat : [];
  const chatKey = String(getChatKey() || '');
  let changed = false;
  for (const record of storyboardGalleryRecords()) {
    if (!record || storyboardRecordChatKey(record, chatKey) !== chatKey) continue;
    if (!record.messageRef?.messageKey) {
      const recovered = storyboardRecoverLegacyMessageReference(record, chat, chatKey);
      if (recovered) { record.messageRef = recovered; changed = true; }
    }
    if (!record.messageRef?.messageKey) continue;
    const resolved = resolveStoryboardMessageReference(record.messageRef, chat, { chatKey });
    const previousFloor = record.floor;
    const previousState = record.linkState || '';
    if (resolved.state === 'active' || resolved.state === 'stale' || resolved.state === 'inactive_swipe') {
      record.floor = resolved.floor;
      record.lastKnownFloor = resolved.floor;
      if (record.messageRef.lastKnownFloor !== resolved.floor) record.messageRef.lastKnownFloor = resolved.floor;
      if (record.paragraphAnchor && record.paragraphAnchor.floor !== resolved.floor) record.paragraphAnchor.floor = resolved.floor;
    } else if (resolved.state === 'orphaned') {
      if (Number.isInteger(previousFloor)) record.lastKnownFloor = previousFloor;
      record.floor = null;
    }
    record.linkState = resolved.state;
    if (previousFloor !== record.floor || previousState !== record.linkState) changed = true;
  }
  if (changed && persist) storyboardScheduleLinkSave();
  return changed;
}

function storyboardRecordStatus(record) {
  if (record?.linkState === 'orphaned') return '原楼层已删除';
  if (record?.linkState === 'stale') return Number.isInteger(record?.floor) ? `第 ${record.floor} 层` : '';
  if (record?.linkState === 'inactive_swipe') return '已切换回复版本';
  if (!Number.isInteger(record?.floor)) return '';
  const message = ctx().chat?.[record.floor];
  if (!message) return '原楼层已不存在';
  if (record.messageHash && record.messageHash !== hashText(String(message.mes || ''))) return '正文已变化';
  if (record.swipeId !== undefined && Number(record.swipeId) !== Number(message.swipe_id || 0)) return '已切换回复版本';
  return `第 ${record.floor} 层`;
}

async function storyboardAttachProductionRecord(record) {
  const policy = storyboardProductionDeliveryPolicy(record);
  if (!record || !policy.requiresExplicitInsert) return false;
  const floor = storyboardCurrentAssistantFloor();
  const message = Number.isInteger(floor) ? ctx().chat?.[floor] : null;
  if (!message) return toast('当前聊天没有可承接画面的正文。', 'warning');
  const accepted = await confirmDialog(
    `引用${policy.sourceLabel}`,
    `将这张画面作为导演剪辑插画放入第 ${floor} 层；只改变画面展示，不会把幕后信息写入正文或角色记忆。是否继续？`,
  );
  if (!accepted) return false;
  const chatKey = String(getChatKey() || '');
  record.floor = floor;
  record.lastKnownFloor = floor;
  record.inline = true;
  record.requestedInline = true;
  record.linkState = 'active';
  record.messageHash = hashText(String(message.mes || ''));
  record.swipeId = Number(message.swipe_id || 0);
  record.messageRef = createStoryboardMessageReference({ message, chatKey, floor });
  record.paragraphAnchor = storyboardAnchorForMessage(message, floor, record.finalPrompt || record.prompt || '', null);
  record.chatKey = chatKey;
  const snapshot = await storyboardReadSnapshotForRecord(record);
  if (snapshot) {
    const nextSnapshot = clone(snapshot);
    nextSnapshot.target = 'floor';
    nextSnapshot.floor = floor;
    nextSnapshot.chatKey = chatKey;
    nextSnapshot.inlineByDefault = true;
    nextSnapshot.messageRef = clone(record.messageRef);
    nextSnapshot.messageHash = record.messageHash;
    nextSnapshot.swipeId = record.swipeId;
    nextSnapshot.paragraphAnchor = clone(record.paragraphAnchor);
    await storyboardStoreSnapshotForRecord(record, nextSnapshot);
  }
  await saveMetadata();
  storyboardRenderInlineImages(floor);
  renderModal();
  toast(`${policy.sourceLabel}已引用至第 ${floor} 层。`, 'success');
  return true;
}

function renderStoryboardQueue() {
  const activeJobs = [...storyboardActiveJobs.values()];
  if (!activeJobs.length && !storyboardQueue.length) return '';
  const activeText = activeJobs.length
    ? `${activeJobs.some((job) => job.discardRequested) ? '正在放弃部分收片' : `正在生成 ${activeJobs.length} 个镜头`}`
    : '正在准备下一项';
  return `<section class="sd-card sd-storyboard-queue-card">
    <div><span class="sd-storyboard-queue-pulse"></span><b>${htmlEscape(activeText)}</b><small>${storyboardQueue.length ? `等待 ${storyboardQueue.length} 项` : '队列已空'}</small></div>
    <div>${activeJobs.length ? `<button type="button" class="sd-btn sd-storyboard-discard-active" ${activeJobs.every((job) => job.discardRequested) ? 'disabled' : ''}>放弃进行中</button>` : ''}${storyboardQueue.length ? '<button type="button" class="sd-btn sd-storyboard-clear-queue">清空等待</button>' : ''}</div>
  </section>`;
}

function storyboardWorldEntryId(book, item, index) {
  const raw = item?.uid ?? item?.id ?? item?.key ?? item?.keys ?? index;
  const token = Array.isArray(raw) ? raw.join('|') : String(raw ?? index);
  return `${book}::${token}`.slice(0, 512);
}

function storyboardWorldEntryTitle(item, index) {
  return String(item?.name || item?.comment || (Array.isArray(item?.key) ? item.key.join(', ') : item?.key) || `世界书条目 ${index + 1}`).trim().slice(0, 160);
}

async function storyboardWarmCompilerWorldEntries({ rerender = false, force = false } = {}) {
  const state = storyboardState();
  const key = `${String(getChatKey() || '')}\u0001${String(ctx().characterId ?? '')}`;
  if (!force && storyboardWorldEntryCache.key === key && !storyboardWorldEntryCache.loading) return storyboardWorldEntryCache.rows;
  if (!force && storyboardWorldEntryCache.loading && storyboardWorldEntryCache.key === key) return storyboardWorldEntryCache.loading;
  storyboardWorldEntryCache = { key, names: [], boundNames: [], books: {}, rows: [], loading: null, error: '' };
  const loading = (async () => {
    try {
      const boundNames = uniqueClean([...detectBoundWorldBookNames(), ...(contextScanCache.boundWorldBookNames || [])]);
      const names = uniqueClean([...boundNames, ...(await listWorldBooks())]);
      const requestedBooks = uniqueClean([...(state.promptCompiler.worldBookNames || []), state.promptCompiler.worldBookView]).filter((name) => names.includes(name));
      const books = {};
      const rows = [];
      for (const book of requestedBooks) {
        let entries = contextScanCache.worldBooks?.[book];
        if (!Array.isArray(entries)) entries = await getWorldBookEntries(book).catch(() => []);
        contextScanCache.worldBooks[book] = entries || [];
        books[book] = entries || [];
        (entries || []).forEach((item, index) => {
          if (item?.enabled === false || item?.disable === true) return;
          rows.push({ id: storyboardWorldEntryId(book, item, index), book, title: storyboardWorldEntryTitle(item, index), item, index });
        });
      }
      storyboardWorldEntryCache.names = names;
      storyboardWorldEntryCache.boundNames = boundNames;
      storyboardWorldEntryCache.books = books;
      storyboardWorldEntryCache.rows = rows.slice(0, 1000);
      storyboardWorldEntryCache.error = '';
      state.promptCompiler.worldBookNames = (state.promptCompiler.worldBookNames || []).filter((name) => names.includes(name));
      if (state.promptCompiler.worldBookView && !names.includes(state.promptCompiler.worldBookView)) state.promptCompiler.worldBookView = '';
      saveSettings();
      return storyboardWorldEntryCache.rows;
    } catch (error) {
      storyboardWorldEntryCache.error = String(error?.message || error || '世界书读取失败');
      return [];
    } finally {
      storyboardWorldEntryCache.loading = null;
      if (rerender && activeTab === 'imagegen' && document.getElementById(MODAL_ID)) renderModal();
    }
  })();
  storyboardWorldEntryCache.loading = loading;
  return loading;
}

async function storyboardLoadCompilerWorldBook(book, { initialize = false } = {}) {
  const state = storyboardState();
  const name = String(book || '').trim();
  if (!name) return [];
  let entries = storyboardWorldEntryCache.books[name];
  if (!Array.isArray(entries)) {
    entries = await getWorldBookEntries(name).catch(() => []);
    storyboardWorldEntryCache.books[name] = entries;
    contextScanCache.worldBooks[name] = entries;
  }
  const otherRows = storyboardWorldEntryCache.rows.filter((row) => row.book !== name);
  const rows = (entries || []).map((item, index) => ({ id: storyboardWorldEntryId(name, item, index), book: name, title: storyboardWorldEntryTitle(item, index), item, index }))
    .filter((row) => row.item?.enabled !== false && row.item?.disable !== true);
  storyboardWorldEntryCache.rows = [...otherRows, ...rows].slice(0, 1000);
  if (initialize && !state.promptCompiler.worldBookInitializedNames.includes(name)) {
    const selected = new Set(state.promptCompiler.worldEntryIds || []);
    rows.forEach((row) => selected.add(row.id));
    state.promptCompiler.worldEntryIds = [...selected].slice(0, 1000);
    state.promptCompiler.worldBookInitializedNames = uniqueClean([...(state.promptCompiler.worldBookInitializedNames || []), name]).slice(0, 100);
  }
  return rows;
}

