function openTheaterReader(scene) {
  if (!scene) return;
  theaterView = { mode: 'read', scene };
  activeTab = 'theater';
  renderModal();
}

// 保存阅读页编辑：更新 scene 内容并重判 HTML，同步到最近一幕与收藏（按 id 匹配）
function saveTheaterSceneEdit(scene, value) {
  const content = String(value || '').trim();
  if (!content) return toast('内容不能为空。', 'warning');
  scene.content = content;
  scene.isHtml = looksLikeHtml(extractTheaterBody(content));
  const t = getTheater();
  if (t.lastOutput && t.lastOutput.id === scene.id) {
    t.lastOutput.content = content;
    t.lastOutput.isHtml = scene.isHtml;
  }
  const fav = t.favorites.find((f) => f.id === scene.id);
  if (fav) { fav.content = content; fav.isHtml = scene.isHtml; }
  saveSettings();
  toast('已保存修改。', 'success');
}

function toggleTheaterFavorite(scene) {
  const t = getTheater();
  const exists = t.favorites.find((f) => f.id === scene.id);
  if (exists) {
    t.favorites = t.favorites.filter((f) => f.id !== scene.id);
    toast('已取消收藏。', 'info');
  } else {
    t.favorites.unshift({ id: scene.id, source: scene.source || '', instruction: scene.instruction, content: scene.content, isHtml: scene.isHtml, createdAt: scene.createdAt || new Date().toISOString() });
    t.favorites = t.favorites.slice(0, 50);
    toast('已收藏这一幕。', 'success');
  }
  saveSettings();
}

// 在浏览器新页面独立阅读当前一幕：HTML 幕原样载入，散文幕包一层阅读排版骨架
/* ── 幕外剧场：全屏阅读 portal（仿伴读阅读器，body 级挂载逃离模态 backdrop-filter 包含块） ── */
// 换掉旧的「浏览器新页面打开」：与伴读阅读页同显示同逻辑——不透明主题底、吸顶返回条、隐滚动条正文、Esc/返回退出。
function unmountTheaterFullscreen() {
  document.getElementById('sd-theater-portal')?.remove();
  document.removeEventListener('keydown', theaterFullscreenEsc, true);
}
function theaterFullscreenEsc(e) {
  if (e.key === 'Escape') { e.stopPropagation(); unmountTheaterFullscreen(); }
}
function openTheaterFullscreen(scene) {
  if (!scene) return;
  const cleaned = extractTheaterBody(String(scene.content || ''));
  const scale = getTheater().readerFontScale || 'medium';
  const bodyHtml = (scene.isHtml || looksLikeHtml(cleaned))
    ? `<iframe class="sd-theater-fs-frame" sandbox="allow-scripts allow-popups allow-forms" srcdoc="${htmlEscape(withHiddenScrollbar(cleaned))}"></iframe>`
    : `<div class="sd-theater-fs-prose sd-reader-prose" data-scale="${scale}">${renderTheaterMarkdown(cleaned)}</div>`;

  unmountTheaterFullscreen();
  const modal = document.getElementById(MODAL_ID);
  const portal = document.createElement('div');
  portal.id = 'sd-theater-portal';
  portal.className = 'sd-reader-portal sd-theater-portal';
  // 复制当前主题变量 + 不透明底（与伴读 portal 同套，永远跟随千幕主题）
  if (modal) {
    const cs = getComputedStyle(modal);
    for (const v of READER_PORTAL_VARS) {
      const val = cs.getPropertyValue(v);
      if (val) portal.style.setProperty(v, val.trim());
    }
  }
  const themeKey = THEME_KEYS.includes(settings.theme) ? settings.theme : 'light';
  const portalBg = READER_PORTAL_BG[themeKey] || READER_PORTAL_BG.light;
  portal.style.background = portalBg;
  portal.style.setProperty('--sd-portal-bg', portalBg);
  portal.innerHTML = `
    <div class="sd-reader-stage sd-theater-fs-stage">
      <div class="sd-reader-topbar sd-theater-fs-bar">
        <button type="button" class="sd-theater-fs-back" title="退出全屏" aria-label="退出全屏"><i class="fa-solid fa-arrow-left"></i></button>
        <span class="sd-reader-chtitle">${htmlEscape(theaterSubtitle(scene) || THEATER_READ_TITLE)}</span>
        <button type="button" class="sd-theater-fs-close" title="关闭" aria-label="关闭"><i class="fa-solid fa-compress"></i></button>
      </div>
      <div class="sd-theater-fs-body sd-scroll">${bodyHtml}</div>
    </div>`;
  document.body.appendChild(portal);
  applyQianmuIcons(portal);
  portal.querySelector('.sd-theater-fs-back')?.addEventListener('click', unmountTheaterFullscreen);
  portal.querySelector('.sd-theater-fs-close')?.addEventListener('click', unmountTheaterFullscreen);
  setTimeout(() => document.addEventListener('keydown', theaterFullscreenEsc, true), 0);
}

function openTheaterFavorites() {
  theaterView = { mode: 'favorites' };
  activeTab = 'theater';
  renderModal();
}

function bindTheaterTabEvents(root) {
  const retryCatalog = root.querySelector('.sd-theater-catalog-retry');
  if (retryCatalog) {
    retryCatalog.addEventListener('click', async () => {
      theaterCatalogError = '';
      retryCatalog.disabled = true;
      await ensureTheaterCatalog();
      if (activeTab === 'theater') renderModal();
    });
    return;
  }
  if (!theaterCatalogReady) return;
  // 阅读 / 收藏夹 内嵌视图
  if (theaterView) {
    root.querySelector('.sd-theater-reader-back')?.addEventListener('click', () => {
      // 编辑态下「返回」先退出编辑回到阅读，避免误丢改动；阅读态再退出阅读
      if (theaterView?.editing) { theaterView.editing = false; renderModal(); return; }
      theaterView = null;
      renderModal();
    });
    if (theaterView.mode === 'read') {
      const scene = theaterView.scene;
      root.querySelector('.sd-reader-fullscreen')?.addEventListener('click', () => openTheaterFullscreen(scene));
      root.querySelector('.sd-reader-edit')?.addEventListener('click', () => { theaterView.editing = true; renderModal(); });
      root.querySelector('.sd-reader-save')?.addEventListener('click', () => {
        const area = root.querySelector('.sd-reader-edit-area');
        if (!area) return;
        saveTheaterSceneEdit(scene, area.value);
        theaterView.editing = false;
        renderModal();
      });
      root.querySelector('.sd-theater-reader-fav')?.addEventListener('click', () => {
        toggleTheaterFavorite(scene);
        const icon = root.querySelector('.sd-theater-reader-fav i');
        setQianmuIconClass(icon, isTheaterFavorited(scene.id) ? 'fa-solid fa-star sd-fav-on' : 'fa-regular fa-star');
      });
      // 字号下拉（仿主题菜单）：点图标开合·选档即应用+存·点菜单外收起
      const fontPick = root.querySelector('.sd-reader-font-pick');
      const fontMenu = fontPick?.querySelector('.sd-reader-font-menu');
      root.querySelector('.sd-reader-font-toggle')?.addEventListener('click', (event) => {
        event.stopPropagation();
        if (!fontMenu) return;
        const willOpen = fontMenu.hidden;
        fontMenu.hidden = !willOpen;
        fontPick.classList.toggle('open', willOpen);
        if (willOpen) {
          const closeOnce = (ev) => {
            if (fontPick.contains(ev.target)) return;
            fontMenu.hidden = true;
            fontPick.classList.remove('open');
            document.removeEventListener('click', closeOnce, true);
          };
          document.addEventListener('click', closeOnce, true);
        }
      });
      root.querySelectorAll('.sd-reader-font-opt').forEach((el) => el.addEventListener('click', () => {
        const next = el.dataset.scale;
        getTheater().readerFontScale = next;
        saveSettings();
        const prose = root.querySelector('.sd-reader-prose');
        if (prose) prose.dataset.scale = next;
        root.querySelectorAll('.sd-reader-font-opt').forEach((b) => {
          const on = b.dataset.scale === next;
          b.classList.toggle('active', on);
          b.setAttribute('aria-checked', on ? 'true' : 'false');
        });
        if (fontMenu) fontMenu.hidden = true;
        fontPick?.classList.remove('open');
      }));
    } else if (theaterView.mode === 'favorites') {
      root.querySelectorAll('.sd-fav-read').forEach((el) => el.addEventListener('click', () => {
        const f = getTheater().favorites.find((x) => x.id === el.dataset.id);
        if (f) openTheaterReader(f);
      }));
      root.querySelectorAll('.sd-fav-remove').forEach((el) => el.addEventListener('click', () => {
        const t = getTheater();
        t.favorites = t.favorites.filter((x) => x.id !== el.dataset.id);
        saveSettings();
        renderModal();
      }));
    }
    return;
  }
  root.querySelector('.sd-theater-api-select')?.addEventListener('change', (e) => {
    getTheater().apiProfileId = e.target.value || '';
    saveSettings();
  });
  root.querySelector('.sd-theater-preset-select')?.addEventListener('change', async (e) => {
    const t = getTheater();
    t.presetName = e.target.value || '';
    if (t.presetName && !contextScanCache.presets?.[t.presetName]) {
      contextScanCache.presets[t.presetName] = getPresetEntries(t.presetName);
    }
    initTheaterPresetSelection(t.presetName);
    saveSettings();
    renderModal();
  });
  root.querySelector('.sd-theater-refresh-preset')?.addEventListener('click', async () => {
    await refreshPresets(false);
    const t = getTheater();
    if (t.presetName) {
      contextScanCache.presets[t.presetName] = getPresetEntries(t.presetName);
      initTheaterPresetSelection(t.presetName);
    }
    toast('预设已读取。', 'success');
    renderModal();
  });
  root.querySelectorAll('.sd-theater-preset-item').forEach((el) => {
    el.addEventListener('click', (event) => event.stopPropagation());
    el.addEventListener('change', () => setTheaterPresetItemSelected(getTheater().presetName, el.dataset.id, el.checked));
  });
  root.querySelector('.sd-theater-use-history')?.addEventListener('change', (e) => {
    getTheater().useChatHistory = e.target.checked;
    saveSettings();
    renderModal();
  });
  root.querySelector('.sd-theater-history-depth')?.addEventListener('change', (e) => {
    getTheater().historyDepth = Math.max(1, Math.min(200, Number(e.target.value || 5)));
    saveSettings();
  });
  root.querySelector('.sd-theater-instruction')?.addEventListener('change', (e) => {
    getTheater().instruction = e.target.value || '';
    theaterScriptSource = '';   // 手动改动指令即视为即兴，脱离剧札来源
    saveSettings();
  });
  root.querySelector('.sd-theater-stage')?.addEventListener('click', () => {
    if (theaterBusy) { stopTheater(); return; }
    const ta = root.querySelector('.sd-theater-instruction');
    if (ta) { getTheater().instruction = ta.value || ''; saveSettings(); }
    stageTheaterScene();
  });
  root.querySelector('.sd-theater-save-script')?.addEventListener('click', async () => {
    const ta = root.querySelector('.sd-theater-instruction');
    const instruction = String(ta?.value || getTheater().instruction || '').trim();
    if (!instruction) return toast('请先写下此幕指令。', 'warning');
    const result = await promptNameAndFolder({ dialogTitle: '保存到剧札', namePlaceholder: '此幕剧名' });
    if (!result) return;
    if (!result.name) return toast('请为这一幕取个剧名。', 'warning');
    const t = getTheater();
    t.scripts.unshift({ id: uid('script'), title: result.name, folder: result.folder || '', instruction, createdAt: new Date().toISOString() });
    t.scripts = normalizeScripts(t.scripts);
    saveSettings();
    toast('已存入剧札。', 'success');
    renderModal();
  });
  root.querySelector('.sd-theater-open-latest')?.addEventListener('click', () => openTheaterReader(getTheater().lastOutput));
  root.querySelector('.sd-theater-open-favorites')?.addEventListener('click', openTheaterFavorites);

  bindLibraryEvents(root, theaterScriptLibraryCfg, {
    onLoad: (id) => {
      const s = getTheater().scripts.find((x) => x.id === id);
      if (!s) return;
      const t = getTheater();
      t.instruction = s.instruction || '';
      theaterScriptSource = s.title || '';   // 记录来源剧札名，供阅读页副标题显示
      saveSettings();
      const ta = root.querySelector('.sd-theater-instruction');
      if (ta) ta.value = t.instruction;
      toast('已载入到此幕指令。', 'success');
    },
    onEdit: async (id) => {
      const t = getTheater();
      const s = t.scripts.find((x) => x.id === id);
      if (!s) return;
      const edited = await promptLibraryEdit({
        dialogTitle: '编辑剧札', nameLabel: '剧札标题', folderLabel: '文件夹', contentLabel: '剧场指令',
        name: s.title, folder: s.folder, content: s.instruction,
      });
      if (edited === null) return;
      if (!edited.content) return toast('剧场指令不能为空。', 'warning');
      if (isBuiltinScript(s)) {
        // 内置项不就地改（更新会被还原），改成派生一份用户副本，内置保持原样
        const fork = { id: uid('script'), title: edited.name || s.title, folder: sanitizeFolder(edited.folder), instruction: edited.content, createdAt: new Date().toISOString() };
        t.scripts = normalizeScripts([fork, ...t.scripts]);
        saveSettings();
        toast('内置剧札不可直接修改，已另存为你的副本。', 'success');
        renderModal();
        return;
      }
      s.title = edited.name || s.title;
      s.folder = edited.folder;
      s.instruction = edited.content;
      saveSettings();
      toast('剧札已更新。', 'success');
      renderModal();
    },
    onDelete: async (id) => {
      const yes = await confirmDialog('删除剧札', '确认删除这个剧札？');
      if (!yes) return;
      const t = getTheater();
      t.scripts = t.scripts.filter((x) => x.id !== id);
      theaterExportSelection.delete(id);
      saveSettings();
      toast('已删除。', 'success');
      renderModal();
    },
    onToggleExport: () => {
      theaterExportMode = !theaterExportMode;
      if (!theaterExportMode) theaterExportSelection.clear();
      renderModal();
    },
    onCancelExport: () => {
      theaterExportMode = false;
      theaterExportSelection.clear();
      renderModal();
    },
    onConfirmExport: () => {
      if (!theaterExportSelection.size) return toast('请先勾选要导出的剧札。', 'warning');
      exportTheaterScripts([...theaterExportSelection]);
      theaterExportMode = false;
      theaterExportSelection.clear();
      renderModal();
    },
    onBatchDelete: async () => {
      if (!theaterExportSelection.size) return toast('请先勾选要删除的剧札。', 'warning');
      const yes = await confirmDialog('批量删除', `确认删除选中的 ${theaterExportSelection.size} 个剧札？`);
      if (!yes) return;
      const t = getTheater();
      t.scripts = (t.scripts || []).filter((x) => !theaterExportSelection.has(x.id));
      theaterExportSelection.clear();
      theaterExportMode = false;
      saveSettings();
      toast('已删除。', 'success');
      renderModal();
    },
    onImport: importTheaterScripts,
  });
}

function exportTheaterScripts(ids = null) {
  const all = getTheater().scripts || [];
  const selectedIds = Array.isArray(ids) ? ids.filter(Boolean) : null;
  const scripts = selectedIds?.length ? all.filter((s) => selectedIds.includes(s.id)) : all;
  if (!scripts.length) return toast('请先选择要导出的剧札。', 'warning');
  const blob = new Blob([JSON.stringify({ version: 1, type: 'theater-scripts', scripts }, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `qianmu-scripts-${fileStamp()}.json`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
  toast(`已导出 ${scripts.length} 篇剧札。`, 'success');
}

async function importTheaterScripts(event) {
  const file = event.target.files?.[0];
  if (!file) return;
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    const incoming = Array.isArray(data) ? data : (data.scripts || data.templates);
    if (!Array.isArray(incoming)) throw new Error('没有找到剧札数组。');
    const t = getTheater();
    const valid = incoming
      .map((item) => ({ item, instruction: item?.instruction || item?.content, title: item?.title || item?.name || '导入剧札' }))
      .filter((x) => x.instruction);
    // 去重只认用户项；与内置同名只视作"撞名"，不覆盖内置，改存成可见的用户副本
    const userByTitle = new Map((t.scripts || []).filter((s) => !isBuiltinScript(s)).map((s) => [s.title, s]));
    const builtinTitles = new Set((t.scripts || []).filter((s) => isBuiltinScript(s)).map((s) => s.title));
    const takenTitles = new Set([...userByTitle.keys(), ...builtinTitles]);
    const uniqueCopyTitle = (base) => {
      if (!takenTitles.has(base)) return base;
      let n = 1;
      while (takenTitles.has(`${base} (${n})`)) n++;
      return `${base} (${n})`;
    };
    const conflictNames = [...new Set(valid.map((x) => x.title).filter((n) => userByTitle.has(n)))];
    const decisions = await resolveImportConflicts(conflictNames);
    if (decisions === null) { toast('已取消导入。', 'info'); return; }
    let added = 0, updated = 0, skipped = 0, copied = 0;
    const fresh = [];
    for (const { item, instruction, title } of valid) {
      const existing = userByTitle.get(title);
      if (existing) {   // 命中用户项：按选择覆盖或跳过（覆盖保留原 id）
        if (decisions.get(title) === 'skip') { skipped++; continue; }
        existing.instruction = instruction;
        existing.folder = sanitizeFolder(item.folder || existing.folder);
        updated++;
        continue;
      }
      // 未命中用户项：若与内置撞名则换个可见副本名，内置保持原样
      const finalTitle = builtinTitles.has(title) ? uniqueCopyTitle(title) : title;
      if (finalTitle !== title) copied++; else added++;
      const script = { id: uid('script'), title: finalTitle, folder: sanitizeFolder(item.folder), instruction, createdAt: item.createdAt || new Date().toISOString() };
      fresh.push(script);
      userByTitle.set(finalTitle, script);
      takenTitles.add(finalTitle);
    }
    // 新条目作为用户剧札插到最前；normalizeScripts 只整顺序、不限数量
    t.scripts = normalizeScripts([...fresh, ...(t.scripts || [])]);
    saveSettings();
    const parts = [`新增 ${added}`, `覆盖 ${updated}`, `跳过 ${skipped}`];
    if (copied) parts.push(`内置同名另存副本 ${copied}`);
    toast(`导入完成：${parts.join('，')}。`, 'success');
    renderModal();
  } catch (error) {
    toast(`导入失败：${error.message}`, 'error');
  } finally {
    event.target.value = '';
  }
}

function renderInputMenuEntry() {
  const existingEntry = document.getElementById(INPUT_ENTRY_ID);
  const existingButton = document.getElementById(INPUT_BUTTON_ID);
  if (!settings.enabled) {
    existingEntry?.remove();
    existingButton?.remove();
    startInputMenuObserver();
    return;
  }
  if (existingEntry?.isConnected || existingButton?.isConnected) {
    startInputMenuObserver();
    return;
  }

  const menu = document.querySelector('#extensionsMenu, #extensions_menu, #input_extra_menu, #send_form_menu, .extensionsMenu');
  if (menu) {
    const entry = document.createElement('div');
    entry.id = INPUT_ENTRY_ID;
    entry.className = 'list-group-item flex-container flexGap5 interactable story-director-input-entry';
    entry.tabIndex = 0;
    entry.innerHTML = `<div class="fa-solid fa-clapperboard extensionsMenuExtensionButton" data-qm-icon="qm-duotone-film-slate"></div><span>${EXTENSION_NAME}</span>`;
    entry.addEventListener('click', () => openModal());   // 恢复上次 tab
    menu.appendChild(entry);
    applyQianmuIcons(entry);
    startInputMenuObserver();
    return;
  }

  const sendForm = document.querySelector('#send_form, #form_sheld, #chat-input, .send_form');
  const textarea = document.querySelector('#send_textarea, textarea#send_textarea');
  const parent = sendForm || textarea?.parentElement;
  if (!parent || parent.querySelector(`#${INPUT_BUTTON_ID}`)) return;
  const button = document.createElement('button');
  button.id = INPUT_BUTTON_ID;
  button.type = 'button';
  button.title = EXTENSION_NAME;
  button.innerHTML = '<i class="fa-solid fa-clapperboard" data-qm-icon="qm-duotone-film-slate"></i>';
  button.addEventListener('click', () => openModal());   // 恢复上次 tab
  if (textarea && textarea.parentElement === parent) parent.insertBefore(button, textarea);
  else parent.insertBefore(button, parent.firstChild);
  applyQianmuIcons(button);
  startInputMenuObserver();
}

function inputMenuObservationRoot() {
  const sendForm = document.querySelector('#send_form, #form_sheld, #chat-input, .send_form');
  const menu = document.querySelector('#extensionsMenu, #extensions_menu, #input_extra_menu, #send_form_menu, .extensionsMenu');
  return sendForm || menu?.parentElement || document.body;
}

function startInputMenuObserver() {
  if (!settings.enabled || !document.body) {
    inputMenuObserver?.disconnect();
    inputMenuObserver = null;
    inputMenuObserverTarget = null;
    return;
  }
  const target = inputMenuObservationRoot();
  if (inputMenuObserver && inputMenuObserverTarget === target) return;
  inputMenuObserver?.disconnect();
  inputMenuObserver = new MutationObserver(() => {
    if (!document.getElementById(INPUT_ENTRY_ID) && !document.getElementById(INPUT_BUTTON_ID)) renderInputMenuEntry();
    if (inputMenuObservationRoot() !== inputMenuObserverTarget) startInputMenuObserver();
  });
  inputMenuObserverTarget = target;
  inputMenuObserver.observe(target, { childList: true, subtree: true });
}

let resizeHandler = null;
let eventBindings = [];

function storyboardResetAutomaticCapture() {
  storyboardAutomaticEpoch++;
  storyboardAutomaticPending.clear();
  if (storyboardAutomaticTimer !== null) clearTimeout(storyboardAutomaticTimer);
  storyboardAutomaticTimer = null;
  const plan = storyboardAutomaticCurrent?.plan;
  // Do not cancel already queued/accepted image jobs just because the reader changed chat.
  if (plan?.origin === 'automatic' && ['screening', 'compiling', 'prompt_ready'].includes(plan.status)) {
    Object.assign(plan, { status: 'cancelled', error: '自动取景环境已变化，未继续自动提交', updatedAt: Date.now() });
  }
  storyboardAutomaticCurrent = null;
}

function storyboardAutomaticTicketFloor(ticket) {
  if (!ticket || ticket.epoch !== storyboardAutomaticEpoch || ticket.state !== storyboardState()
    || ticket.chatKey !== String(getChatKey() || '') || Date.now() - ticket.createdAt > 5 * 60_000) return -1;
  const state = ticket.state;
  if (!state.enabled || !state.automation?.autoCapture || !state.promptCompiler?.enabled) return -1;
  const chat = ctx().chat || [];
  const floor = chat[ticket.floor] === ticket.message ? ticket.floor : chat.indexOf(ticket.message);
  if (floor < 0 || ticket.message.is_user || ticket.message.is_system) return -1;
  const current = createStoryboardMessageReference({ message: ticket.message, chatKey: ticket.chatKey, floor });
  return current.messageKey === ticket.messageRef.messageKey && current.revisionId === ticket.messageRef.revisionId ? floor : -1;
}

function storyboardScheduleAutomaticCapture() {
  if (!storyboardAutomaticPending.size || storyboardAutomaticCurrent || storyboardCompilerBusy || storyboardAutomaticTimer !== null) return;
  // One event-loop handoff, not a repeating timer. Compiler completion wakes the queue.
  storyboardAutomaticTimer = setTimeout(() => {
    storyboardAutomaticTimer = null;
    void storyboardDrainAutomaticCapture().catch(error => console.warn(`[${MODULE_NAME}] automatic storyboard capture failed`, error));
  }, 0);
}

async function storyboardDrainAutomaticCapture() {
  if (storyboardAutomaticCurrent || storyboardCompilerBusy) return false;
  const entry = storyboardAutomaticPending.entries().next().value;
  if (!entry) return false;
  const [key, ticket] = entry;
  storyboardAutomaticPending.delete(key);
  storyboardAutomaticCurrent = ticket;
  try { return await storyboardPerformAutomaticCapture(ticket); }
  catch (error) {
    if (ticket.plan && ['screening', 'compiling'].includes(ticket.plan.status)) {
      Object.assign(ticket.plan, { status: 'failed', error: '自动取景准备失败，请手动重新提取', updatedAt: Date.now() });
      if (storyboardAutomaticTicketFloor(ticket) >= 0) { saveSettings(); toast(ticket.plan.error, 'warning'); }
    }
    console.warn(`[${MODULE_NAME}] automatic storyboard capture failed`, error);
    return false;
  }
  finally {
    if (storyboardAutomaticCurrent === ticket) storyboardAutomaticCurrent = null;
    storyboardScheduleAutomaticCapture();
  }
}

async function storyboardHandleAutomaticCapture(messageIndex) {
  const state = storyboardState();
  if (!state.enabled || !state.automation?.autoCapture || !state.promptCompiler?.enabled) return false;
  const receivedIndex = typeof messageIndex === 'string' && /^\d+$/.test(messageIndex) ? Number(messageIndex) : messageIndex;
  const floor = Number.isInteger(receivedIndex) ? receivedIndex : storyboardCurrentAssistantFloor();
  const message = floor >= 0 ? ctx().chat?.[floor] : null;
  if (!message || message.is_user || message.is_system || !String(message.mes || '').trim()) return false;
  const existing = storyboardPlanForMessage(state, floor, message);
  // A repeated host event is not authorization to retry a failed/uncertain paid request.
  if (existing && (existing.status !== 'idle' || existing.origin !== 'automatic' || existing.promptLocked || existing.manualReviewRequired)) return false;
  const chatKey = String(getChatKey() || '');
  if (!chatKey) return false;
  const messageRef = createStoryboardMessageReference({ message, chatKey, floor });
  const key = JSON.stringify([chatKey, messageRef.messageKey, messageRef.revisionId]);
  if (storyboardAutomaticPending.has(key) || storyboardAutomaticCurrent?.key === key) return false;
  if (storyboardAutomaticPending.size >= STORYBOARD_QUEUE_LIMIT) {
    toast('自动取景等待已满，本层可稍后手动提取', 'info');
    return false;
  }
  storyboardAutomaticPending.set(key, { key, epoch: storyboardAutomaticEpoch, state, chatKey, floor, message, messageRef, createdAt: Date.now(), autoGenerate: Boolean(state.automation.autoGenerate) });
  storyboardScheduleAutomaticCapture();
  return true;
}

async function storyboardPerformAutomaticCapture(ticket) {
  const floor = storyboardAutomaticTicketFloor(ticket);
  if (floor < 0) return false;
  const { state, message } = ticket;
  const existing = storyboardPlanForMessage(state, floor, message);
  if (existing && (existing.status !== 'idle' || existing.origin !== 'automatic' || existing.promptLocked || existing.manualReviewRequired)) return false;
  const plan = existing || storyboardEnsurePlan(state, floor, message, {
    origin: 'automatic', autoGenerate: ticket.autoGenerate && state.automation.autoGenerate,
  });
  ticket.plan = plan;
  // Reserve before awaiting archive I/O; a duplicate receipt cannot start the same LLM twice.
  plan.status = 'screening';
  plan.updatedAt = Date.now();
  saveSettings();
  if (plan.archiveRef) await storyboardReleasePlanArchive(plan);
  if (storyboardAutomaticTicketFloor(ticket) !== floor || !state.shotPlans.includes(plan) || plan.status !== 'screening') {
    if (plan.status === 'screening') Object.assign(plan, { status: 'cancelled', error: '原正文已变化，未继续自动取景', updatedAt: Date.now() });
    return false;
  }
  plan.origin = 'automatic';
  plan.autoGenerate = Boolean(ticket.autoGenerate && state.automation.autoGenerate);
  plan.updatedAt = Date.now();
  state.target = 'floor';
  state.floor = String(floor);
  state.paragraphMode = 'auto';
  state.manualParagraphIndex = null;
  state.pendingParagraphSelection = null;
  state.promptMode = 'auto';
  state.prompt = '';
  state.negative = '';
  state.promptDraft.compiled = '';
  state.promptDraft.negative = '';
  state.promptDraft.shots = [];
  state.promptDraft.userEditedCompiled = false;
  state.promptDraft.userEditedNegative = false;
  state.promptDraft.artistPositiveBaked = false;
  state.promptDraft.artistNegativeBaked = false;
  saveSettings();
  storyboardScheduleInlineRender(20, floor);
  const compiled = await storyboardCompilePrompt(null, { plan, quiet: true, automatic: plan.autoGenerate });
  if (!compiled && plan.status === 'screening') {
    Object.assign(plan, { status: 'failed', error: '取景未启动，请核对配置后手动重试', updatedAt: Date.now() });
    if (storyboardAutomaticTicketFloor(ticket) >= 0) saveSettings();
  }
  if (!compiled || !plan.autoGenerate || !ticket.autoGenerate || !state.automation.autoGenerate || storyboardAutomaticTicketFloor(ticket) !== floor) return compiled;
  return storyboardGenerate(null, { plan, automatic: true });
}

function unbindEvents() {
  const source = ctx().eventSource;
  if (source?.off) {
    for (const [type, handler] of eventBindings) source.off(type, handler);
  }
  eventBindings = [];
  eventBound = false;
}

function bindEvents() {
  if (eventBound) return;
  const context = ctx();
  const source = context.eventSource;
  const types = context.event_types || {};
  if (!source?.on) return;
  eventBound = true;
  // 自动推演触发：每有新角色回复（MESSAGE_RECEIVED）就照实数一遍——以 lastPlanIdx 为基准，统计其后真正新增的
  // 角色回复层，满阈值即刻推演、读取当下完整聊天。重 roll 同层改写不新增索引、天然不计；删楼则把基准夹回当前末尾自动重算。
  const runBackgroundDirectorRefresh = async () => {
    try {
      if (!settings.enabled) return;
      const chat = ctx().chat;
      const len = Array.isArray(chat) ? chat.length : 0;
      const store = getChatStore();
      let mark = Number(store.lastPlanIdx ?? -1);
      let metadataChanged = false;
      if (mark < 0 || mark > len - 1) {
        mark = len - 1;   // 首次启用/删楼后：基准夹到当前末尾，既不漏数也不让历史楼层一次触发
        if (Number(store.lastPlanIdx) !== mark) { store.lastPlanIdx = mark; metadataChanged = true; }
      }
      let layers = 0;                                    // 基准之后真正新增的「角色回复」层（你发的楼、system 都不计）
      for (let i = mark + 1; i < len; i++) {
        const m = chat[i];
        if (m && !m.is_user && !m.is_system) layers++;
      }
      if (settings.autoRefresh && settings.autoRefreshEvery > 0 && !busy && layers >= settings.autoRefreshEvery) {
        store.lastPlanIdx = len - 1;                     // 以当前末尾为新基准，下一轮重新累积
        await saveMetadata();
        await generateDirectorPlan(false, true, { background: true });
      } else {
        // 计数由聊天长度相对固定基准实时得出；无状态变化时不重写整份聊天 metadata。
        if (metadataChanged) await saveMetadata();
      }
    } catch (error) {
      console.warn(`[${MODULE_NAME}] auto refresh handler failed`, error);
    }
  };
  const refreshHandler = (messageIndex) => {
    resetDirectorNarrativeBridge();
    storyboardScheduleInlineRender(120);
    void storyboardHandleAutomaticCapture(messageIndex).catch((error) => console.warn(`[${MODULE_NAME}] automatic storyboard capture failed`, error));
    queueMicrotask(() => void runBackgroundDirectorRefresh());
  };
  const rerenderHandler = async () => {
    storyboardResetAutomaticCapture();
    storyboardCloseVideoDraftEditor();
    resetDirectorNarrativeBridge();
    settings = getSettings();
    if (isPlainObject(settings.imagegen)) normalizeStoryboardState(settings.imagegen);
    injectSelection.clear();   // 切换聊天后旧写入勾选失效
    // 新角色/聊天可能绑定了不同世界书：作废世界书扫描态，下次推演或开取材页自动补扫（预设不随角色变，留存）
    contextScanCache.worldScannedAt = '';
    contextScanCache.boundWorldBookNames = [];
    contextAutoScanned = false;
    ttsLineCache.clear();      // 切聊天：旧消息台词缓存失效
    coreadInvalidatePool();    // 切聊天：反哺主线切片池随新聊天的绑定档案重算
    companionWorldView = '';   // 切聊天：世界书已按聊天分存，查看视图回到未选·避免跨聊天残留
    await refreshCoreadPersonaAvatar();
    void storyboardHandleChatChanged();
    storyboardSchedulePlanArchive(1200);
    applyProseLayout();
    renderFloatButton();
    renderInputMenuEntry();
    await applyDirectorInjection();
    rerenderIfOpen();
    ttsStartChat();            // 新聊天 DOM 重建，重挂注入
    storyboardScheduleInlineRender(140);
  };
  // APP_READY：ST 注水 extensionSettings 完成的信号。init 经 setTimeout 抢跑可能早于注水，
  // 此时读到的 floatPosition 仍是默认 → 悬浮球落默认中位。注水后重读 settings 并按保存位重绘，根治「重载后球回默认位」偶发。
  const appReadyHandler = async () => {
    settings = getSettings();
    if (isPlainObject(settings.imagegen)) normalizeStoryboardState(settings.imagegen);
    focusClockState();
    focusClockRuntimeTick();
    await refreshCoreadPersonaAvatar();
    void storyboardHandleChatChanged();
    storyboardSchedulePlanArchive(1200);
    applyProseLayout();
    renderFloatButton();
    restoreQuickDockedPlugins();
    rerenderIfOpen();
    ttsStartChat();   // ST 就绪后 #chat 已存在，挂上有声注入（init 抢跑时 #chat 可能尚未就位）
    storyboardScheduleInlineRender(160);
  };
  const personaChangedHandler = async () => {
    await refreshCoreadPersonaAvatar();
    rerenderIfOpen();
  };
  // 原地编辑正文：刻意不复位缓存——保留已提取台词与已生成音频，交用户手动决定（🔁 全量重提取 / 双击单句更新）。
  // 但 ST 保存编辑会重渲 .mes_text 内部 HTML，抹掉注入其中的内联 🔊（工具栏/台词条是兄弟节点、不受影响）。
  // 故只触发一次防抖扫描，由 ttsAutoRestore 的「自愈」分支按缓存幂等补回内联图标（延时让 ST 重渲先落定）。
  const ttsMessageEditedHandler = (messageRef) => {
    resetDirectorNarrativeBridge();
    const t = settings.tts || {};
    if (t.enabled && t.injectInChat) ttsScheduleEditedMessage(messageRef, 250);
    storyboardScheduleInlineRender(280);
  };
  const storyboardMessageDeletedHandler = async () => {
    resetDirectorNarrativeBridge();
    await applyDirectorInjection();
    storyboardScheduleInlineRender(140);
  };
  const storyboardMessageVersionHandler = () => {
    resetDirectorNarrativeBridge();
    storyboardScheduleInlineRender(180);
  };
  const storyboardMoreMessagesLoadedHandler = () => storyboardScheduleInlineRender(180);
  const pairs = [
    [types.APP_READY || 'app_ready', appReadyHandler],   // 注水后把悬浮球挪回上次拖动的位置（修偶发回默认位）
    [types.PERSONA_CHANGED || 'persona_changed', personaChangedHandler],   // 冷启动即读 ST 当前头像；切换人设后同步伴读设定
    [types.MESSAGE_RECEIVED || 'message_received', refreshHandler],   // 仅角色回复触发；重 roll/删楼由 refreshHandler 照实重算
    [types.MESSAGE_DELETED || 'message_deleted', storyboardMessageDeletedHandler],   // 删楼重判推演注入，并把分镜成片转为可恢复的孤儿记录
    [types.MESSAGE_EDITED || 'message_edited', ttsMessageEditedHandler],   // 原地编辑：仅按缓存补回被重渲抹掉的内联 🔊（不动列表/音频/key）
    [types.MESSAGE_SWIPED || 'message_swiped', storyboardMessageVersionHandler],
    [types.MESSAGE_SWIPE_DELETED || 'message_swipe_deleted', storyboardMessageVersionHandler],
    [types.MORE_MESSAGES_LOADED || 'more_messages_loaded', storyboardMoreMessagesLoadedHandler],
    [types.CHAT_CHANGED || 'chat_changed', rerenderHandler],
    [types.GROUP_UPDATED || 'group_updated', rerenderHandler],
    [types.CHARACTER_SELECTED || 'character_selected', rerenderHandler],
  ];
  for (const [type, handler] of pairs) {
    source.on(type, handler);
    eventBindings.push([type, handler]);
  }
}

function init() {
  if (initialized || !acquireRuntimeOwnership()) return;
  try {
    const initStartedAt = globalThis.performance?.now?.() ?? Date.now();
    settings = getSettings();
    if (isPlainObject(settings.imagegen)) normalizeStoryboardState(settings.imagegen);
    focusClockState();
    startFocusClockRuntime();
    void refreshCoreadPersonaAvatar()
      .then(() => rerenderIfOpen())
      .catch((error) => console.warn(`[${MODULE_NAME}] persona initialization failed`, error));
    applyProseLayout();
    renderSettingsPanel();
    renderFloatButton();
    bindQuickDockCapture();
    restoreQuickDockedPlugins();
    storyboardBindChat();
    renderInputMenuEntry();
    startInputMenuObserver();

    resizeHandler = () => {
      closeQuickWheel();
      const btn = document.getElementById(FLOAT_ID);
      if (btn) applyFloatPosition(btn);
      const tabsBar = document.getElementById(MODAL_ID)?.querySelector('.sd-tabs');
      if (tabsBar) updateTabsFade(tabsBar);
      renderFloatingNotes();
      if (notesPanelOpen) syncNotesPanelSizeToViewport();
    };
    window.addEventListener('resize', resizeHandler);
    bindEvents();
    void applyDirectorInjection();
    ttsStartChat();   // 若 ST 已就绪则即刻挂注入；未就绪由 APP_READY 兜底
    registerRuntimeInterceptor();
    initialized = true;
    startFloatHostGuard();
    const initFinishedAt = globalThis.performance?.now?.() ?? Date.now();
    performanceRuntime.initMs = Math.max(0, initFinishedAt - initStartedAt);
    performanceRuntime.readyMs = Math.max(0, initFinishedAt - MODULE_EXECUTION_STARTED_AT);
    console.log(`[${EXTENSION_NAME}] v${VERSION} loaded`);
  } catch (error) {
    console.error(`[${EXTENSION_NAME}] v${VERSION} initialization failed`, error);
    cleanupRuntime(false);
  }
}

export async function onActivate() {
  handleLifecycle();
  init();
}

export async function onEnable() {
  handleLifecycle();
  init();
}

export async function onDisable() {
  handleLifecycle();
  cleanupRuntime(false);
}

export async function onUpdate() {
  handleLifecycle();
  // ST 在拉取新文件后调用 update，但现有 ES module 仍驻留内存，真正切换版本必须刷新页面。
  // 保留旧运行时到刷新完成，避免更新提示出现后悬浮入口、任务和面板被提前拆除。
  if (!isRuntimeOwner()) return;
  renderFloatButton();
  startFloatHostGuard();
  console.info(`[${EXTENSION_NAME}] 更新已安装；当前页面继续由 v${VERSION} 运行，刷新后加载新版本。`);
}

export async function onDelete() {
  handleLifecycle();
  cleanupRuntime(false);
}

function cleanupRuntime(resetSettings = false) {
  cancelStartupFallback();
  if (!isRuntimeOwner()) return;
  initialized = false;
  const clean = (label, callback) => {
    try { callback(); } catch (error) { console.warn(`[${MODULE_NAME}] cleanup ${label} failed`, error); }
  };
  try {
    clean('float host guard', () => stopFloatHostGuard());
    clean('quick dock', () => unbindQuickDockCapture());
    clean('float reveal', () => {
      if (floatRevealOutsideHandler) document.removeEventListener('pointerdown', floatRevealOutsideHandler, true);
      floatRevealOutsideHandler = null;
    });
    clean('injection', () => clearDirectorInjection());
    clean('panels', () => {
      storyboardComfyLibraryController?.dispose();
      storyboardComfyLibraryController = null;
      document.getElementById(SETTINGS_PANEL_ID)?.remove();
      document.getElementById(MODAL_ID)?.remove();
      document.getElementById(FLOAT_ID)?.remove();
      document.getElementById(INPUT_ENTRY_ID)?.remove();
      document.getElementById(INPUT_BUTTON_ID)?.remove();
      document.getElementById(NOTES_FLOAT_LAYER_ID)?.remove();
      document.getElementById(NOTES_PANEL_LAYER_ID)?.remove();
      document.getElementById(STORAGE_CLEANUP_LAYER_ID)?.remove();
      notesPanelOpen = false;
    });
    clean('wheel', () => closeQuickWheel());
    clean('floor navigator', () => closeFloorNavigator());
    clean('input observer', () => {
      inputMenuObserver?.disconnect?.();
      inputMenuObserver = null;
      inputMenuObserverTarget = null;
    });
    clean('speech', () => ttsStopChat());
    clean('storyboard queue', () => {
      storyboardResetAutomaticCapture();
      storyboardAdmissionEpoch++;
      void storyboardAdmission?.close();
      storyboardAdmission = null;
      storyboardImageChannel?.close(); storyboardImageChannel = null;
      storyboardImageService?.close(); storyboardImageService = null;
      storyboardComfyRecovery?.close(); storyboardComfyRecovery = null;
      for (const job of storyboardActiveJobs.values()) {
        job.discardRequested = true;
        storyboardSyncTaskState(job, 'cancelled', { error: '扩展已停用或更新', plan: storyboardPlanForJob(job) });
      }
      if (storyboardQueue.length && settings?.imagegen?.logs) {
        for (const job of storyboardQueue) {
          storyboardSyncTaskState(job, 'cancelled', { error: '扩展已停用或更新', plan: storyboardPlanForJob(job) });
          storyboardFinishLog(settings.imagegen.logs.find((item) => item.id === job.logId), 'cancelled', { error: '扩展已停用或更新' });
        }
      }
      storyboardQueue = [];
      saveSettings();
      storyboardRuntimeReconciled = false;
      storyboardPipelineArchiveEpoch++;
      storyboardPipelineArchiveCache.clear();
      storyboardPipelineArchiveWrites.clear();
      storyboardSnapshotEpoch++;
      storyboardSnapshotCache.clear();
      storyboardSnapshotReads.clear();
      storyboardPlanArchiveEpoch++;
      if (storyboardPlanArchiveTimer) clearTimeout(storyboardPlanArchiveTimer);
      storyboardPlanArchiveTimer = null;
      storyboardPlanArchiveCache.clear();
    });
    clean('storyboard events', () => storyboardUnbindChat());
    clean('director candidate pool', () => resetDirectorNarrativeBridge());
    clean('video gallery', () => {
      storyboardCloseVideoViewer();
      storyboardCloseFilmViewer();
      storyboardCloseVideoDraftEditor();
      storyboardVideoGallerySession?.dispose?.();
      storyboardVideoGallerySession = null;
      storyboardVideoCoordinator?.dispose?.();
      storyboardVideoCoordinator = null;
      storyboardVideoCoordinatorLoading = null;
      storyboardVideoTaskStore = null;
      storyboardVideoDraftStore = null;
      storyboardVideoTimelineStore = null;
      storyboardVideoPostproductionStore = null;
      Object.assign(storyboardVideoGalleryRuntime, { chatKey: '', status: 'idle', requestId: storyboardVideoGalleryRuntime.requestId + 1, chains: [], tasks: [], drafts: [], error: '', mediaError: '', taskError: '', draftError: '' });
      Object.assign(storyboardInlineVideoRuntime, { chatKey: '', status: 'idle', requestId: storyboardInlineVideoRuntime.requestId + 1, chains: [] });
      Object.assign(storyboardFilmRuntime, { chatKey: '', status: 'idle', requestId: storyboardFilmRuntime.requestId + 1, timelines: [], motionChains: [], error: '', timelineError: '', mediaError: '' });
      storyboardFilmEditor = null;
    });
    clean('focus clock', () => stopFocusClockRuntime());
    clean('notes', () => {
      stopNotesPanelResizeTracking();
      for (const timer of notesSaveTimers.values()) clearTimeout(timer);
      notesSaveTimers.clear();
      clearTemporaryQianmuNotes();
      notesRuntime = [];
      notesLoaded = false;
      notesLoading = null;
      notesPanelOpen = false;
    });
    clean('prose layout', () => stopProseLayout(true));
    clean('resize', () => {
      if (resizeHandler) window.removeEventListener('resize', resizeHandler);
      resizeHandler = null;
    });
    clean('SillyTavern events', () => unbindEvents());
    if (resetSettings) clean('settings', () => {
      if (ctx().extensionSettings) delete ctx().extensionSettings[MODULE_NAME];
    });
  } finally {
    releaseRuntimeOwnership();
  }
}

installStartupFallback();
